import { Textarea } from '@/components/ui/textarea';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Loader2, Sparkles, Copy, ShoppingBag, Users, BrainCircuit } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { handleProductDescriptionGeneration } from '@/app/actions';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface GenerateProductDescriptionOutput {
  shopify: {
    title: string;
    description: string;
  };
  amazon: {
    title: string;
    bulletPoints: string[];
  };
  socialMedia: {
    instagram: string;
    facebook: string;
  };
}


const formSchema = z.object({
  productName: z.string().min(3, 'Product name must be at least 3 characters.'),
  features: z.string().min(10, 'Please list at least one key feature.'),
  targetAudience: z.string().min(3, 'Target audience is required.'),
  tone: z.string().min(1, 'Please select a tone.'),
});

type FormValues = z.infer<typeof formSchema>;

export function AiProductDescriptionGenerator() {
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<GenerateProductDescriptionOutput | null>(null);
  const [activeTab, setActiveTab] = useState('shopify');
  const { toast } = useToast();

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      productName: '',
      features: '',
      targetAudience: '',
      tone: 'persuasive',
    },
    mode: 'onChange',
  });
  
  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: "Copied to clipboard!" });
  };

  const onSubmit = async (data: FormValues) => {
    setIsLoading(true);
    setResult(null);

    try {
      const response = await handleProductDescriptionGeneration(data);
      if (response.error) {
        throw new Error(response.error);
      }
      setResult(response.data as GenerateProductDescriptionOutput);
      toast({
        title: 'Descriptions Generated!',
        description: 'Your AI-powered product descriptions are ready.',
      });
    } catch (error: any) {
      toast({
        title: 'Generation Failed',
        description: error.message || 'An unexpected error occurred.',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Product Details</CardTitle>
                <CardDescription>Enter your product information below to generate descriptions.</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <FormField
                  control={form.control}
                  name="productName"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className='flex items-center gap-2'><ShoppingBag/>Product Name</FormLabel>
                      <FormControl>
                        <Input placeholder="e.g., 'Eco-Friendly Bamboo Toothbrush'" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="features"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className='flex items-center gap-2'><Sparkles/>Key Features & Benefits</FormLabel>
                      <FormControl>
                        <Textarea
                          placeholder="List the main features, one per line. e.g.,&#10;- 100% biodegradable handle&#10;- Soft, charcoal-infused bristles&#10;- Vegan and cruelty-free"
                          rows={4}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="targetAudience"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className='flex items-center gap-2'><Users/>Target Audience</FormLabel>
                      <FormControl>
                        <Input placeholder="e.g., 'Eco-conscious millennials'" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                 <FormField
                  control={form.control}
                  name="tone"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className='flex items-center gap-2'><BrainCircuit/>Tone of Voice</FormLabel>
                       <Select onValueChange={field.onChange} defaultValue={field.value}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="Select a tone" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="persuasive">Persuasive & Exciting</SelectItem>
                          <SelectItem value="professional">Professional & Technical</SelectItem>
                          <SelectItem value="friendly">Friendly & Casual</SelectItem>
                          <SelectItem value="luxury">Luxury & Elegant</SelectItem>
                          <SelectItem value="minimalist">Minimalist & Direct</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>
            <Button type="submit" className="w-full h-12 text-lg" disabled={isLoading || !form.formState.isValid}>
              {isLoading ? <Loader2 className="mr-2 h-5 w-5 animate-spin" /> : <Sparkles className="mr-2 h-5 w-5" />}
              Generate Descriptions
            </Button>
          </form>
        </Form>
      </div>
      <div className="lg:col-span-3 space-y-4">
        <Card>
          <CardHeader>
            <CardTitle>Generated Descriptions</CardTitle>
            <CardDescription>
              AI-generated content for various e-commerce platforms.
            </CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading && (
              <div className="flex flex-col items-center justify-center text-center p-8 h-96">
                <Loader2 className="h-12 w-12 text-primary animate-spin mb-4" />
                <h3 className="text-xl font-semibold">Generating Content...</h3>
                <p className="text-muted-foreground max-w-sm">
                  The AI is crafting compelling descriptions for your product.
                </p>
              </div>
            )}
            {!isLoading && !result && (
              <div className="text-center py-12 text-muted-foreground border-2 border-dashed rounded-lg h-96 flex items-center justify-center">
                <p>Your product descriptions will appear here.</p>
              </div>
            )}
            {!isLoading && result && (
              <div className="space-y-6">
                <div className="flex justify-center flex-wrap gap-2">
                    <Button variant={activeTab === 'shopify' ? 'default' : 'outline'} onClick={() => setActiveTab('shopify')}>Shopify / General</Button>
                    <Button variant={activeTab === 'amazon' ? 'default' : 'outline'} onClick={() => setActiveTab('amazon')}>Amazon</Button>
                    <Button variant={activeTab === 'social' ? 'default' : 'outline'} onClick={() => setActiveTab('social')}>Social Media</Button>
                </div>
                
                {activeTab === 'shopify' && (
                    <Card>
                        <CardHeader><CardTitle>Shopify / General E-commerce</CardTitle></CardHeader>
                        <CardContent className='space-y-4'>
                            <div className="space-y-2">
                                <h4 className="font-semibold text-sm">Product Title</h4>
                                <div className="flex items-start gap-2">
                                    <p className="text-sm p-3 bg-muted rounded-md text-muted-foreground flex-grow">{result.shopify.title}</p>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(result.shopify.title)}><Copy/></Button>
                                </div>
                            </div>
                            <div className="space-y-2">
                                <h4 className="font-semibold text-sm">Product Description</h4>
                                <div className="flex items-start gap-2">
                                     <div className="text-sm p-3 bg-muted rounded-md text-muted-foreground flex-grow prose prose-sm dark:prose-invert max-w-none" dangerouslySetInnerHTML={{ __html: result.shopify.description.replace(/\n/g, '<br/>') }}></div>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(result.shopify.description)}><Copy/></Button>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                )}
                 {activeTab === 'amazon' && (
                    <Card>
                        <CardHeader><CardTitle>Amazon Listing</CardTitle></CardHeader>
                        <CardContent className='space-y-4'>
                            <div className="space-y-2">
                                <h4 className="font-semibold text-sm">Product Title</h4>
                                <div className="flex items-start gap-2">
                                    <p className="text-sm p-3 bg-muted rounded-md text-muted-foreground flex-grow">{result.amazon.title}</p>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(result.amazon.title)}><Copy/></Button>
                                </div>
                            </div>
                            <div className="space-y-2">
                                <h4 className="font-semibold text-sm">Bullet Points</h4>
                                <div className="flex items-start gap-2">
                                     <div className="text-sm p-3 bg-muted rounded-md text-muted-foreground flex-grow prose prose-sm dark:prose-invert max-w-none" dangerouslySetInnerHTML={{ __html: result.amazon.bulletPoints.map(b => `• ${b}`).join('<br/>') }}></div>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(result.amazon.bulletPoints.join('\n'))}><Copy/></Button>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                )}
                 {activeTab === 'social' && (
                    <Card>
                        <CardHeader><CardTitle>Social Media Posts</CardTitle></CardHeader>
                        <CardContent className='space-y-4'>
                            <div className="space-y-2">
                                <h4 className="font-semibold text-sm">Instagram Post</h4>
                                <div className="flex items-start gap-2">
                                    <p className="text-sm p-3 bg-muted rounded-md text-muted-foreground flex-grow whitespace-pre-wrap">{result.socialMedia.instagram}</p>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(result.socialMedia.instagram)}><Copy/></Button>
                                </div>
                            </div>
                             <div className="space-y-2">
                                <h4 className="font-semibold text-sm">Facebook Post</h4>
                                <div className="flex items-start gap-2">
                                    <p className="text-sm p-3 bg-muted rounded-md text-muted-foreground flex-grow whitespace-pre-wrap">{result.socialMedia.facebook}</p>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(result.socialMedia.facebook)}><Copy/></Button>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Calculator, AlertTriangle, Loader2, LineChart, PieChart, Landmark, DollarSign, Scale, Sparkles, Globe } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useToast } from '@/hooks/use-toast';
import { handleFinancialsGeneration } from '@/app/actions';

const valuationSchema = z.object({
  revenue: z.coerce.number().min(10000, "Must be at least 10,000"),
  opex: z.coerce.number().min(0, "Cannot be negative"),
  depreciation: z.coerce.number().min(0, "Cannot be negative"),
  capex: z.coerce.number().min(0, "Cannot be negative"),
  workingCapitalChange: z.coerce.number(),
  taxRate: z.coerce.number().min(0).max(100),
  growthRate: z.coerce.number().min(-50).max(100),
  discountRate: z.coerce.number().min(5).max(30),
  industry: z.string().min(1, "Please select an industry"),
  // SDE Fields
  ownerSalary: z.coerce.number().min(0).optional(),
  addBacks: z.coerce.number().min(0).optional(),
  // Asset-Based Fields
  totalAssets: z.coerce.number().min(0).optional(),
  totalLiabilities: z.coerce.number().min(0).optional(),
});
type ValuationFormData = z.infer<typeof valuationSchema>;

const industryMultipliers = {
  'saas': { revenue: 8, profit: 20, sde: 5 },
  'ecommerce': { revenue: 2, profit: 12, sde: 3.5 },
  'service': { revenue: 3, profit: 10, sde: 3 },
  'manufacturing': { revenue: 1.5, profit: 8, sde: 4 },
  'biotech': { revenue: 15, profit: 30, sde: 6 },
};
type Industry = keyof typeof industryMultipliers;

interface ValuationResult {
  earningsValuation: { revenue: number, profit: number, sde: number };
  dcfValuation: number;
  assetValuation: { nav: number };
}

type Country = 'US' | 'IN' | 'GB' | 'CA' | 'AU' | 'DE';
const countries: { code: Country, name: string, currency: string, locale: string }[] = [
    { code: 'US', name: 'United States', currency: 'USD', locale: 'en-US' },
    { code: 'IN', name: 'India', currency: 'INR', locale: 'en-IN' },
    { code: 'GB', name: 'United Kingdom', currency: 'GBP', locale: 'en-GB' },
    { code: 'CA', name: 'Canada', currency: 'CAD', locale: 'en-CA' },
    { code: 'AU', name: 'Australia', currency: 'AUD', locale: 'en-AU' },
    { code: 'DE', name: 'Germany', currency: 'EUR', locale: 'de-DE' },
]

export function BusinessValuationCalculator() {
  const [valuationResult, setValuationResult] = useState<ValuationResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isProcessingAi, setIsProcessingAi] = useState(false);
  const [country, setCountry] = useState<Country>('US');
  const aiPromptRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  useEffect(() => {
    try {
        const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        if (timeZone.startsWith('Asia/')) {
            setCountry('IN');
        } else if (timeZone.startsWith('Europe/')) {
            setCountry('GB');
        } else {
            setCountry('US');
        }
    } catch (error) {
        console.error("Could not detect timezone, defaulting to US.");
        setCountry('US');
    }
  }, []);
  
  const isIndia = country === 'IN';

  const form = useForm<ValuationFormData>({
    resolver: zodResolver(valuationSchema),
    defaultValues: {
      revenue: isIndia ? 5000000 : 500000,
      opex: isIndia ? 3000000 : 300000,
      depreciation: isIndia ? 250000 : 25000,
      capex: isIndia ? 400000 : 40000,
      workingCapitalChange: isIndia ? 100000 : 10000,
      taxRate: 21,
      growthRate: 15,
      discountRate: 12,
      industry: 'saas',
      ownerSalary: isIndia ? 1200000 : 80000,
      addBacks: isIndia ? 100000 : 10000,
      totalAssets: isIndia ? 4000000 : 400000,
      totalLiabilities: isIndia ? 1500000 : 150000,
    },
    mode: 'onChange',
  });
  
  const { reset } = form;
  useEffect(() => {
      const isIndia = country === 'IN';
      reset({
        revenue: isIndia ? 5000000 : 500000,
        opex: isIndia ? 3000000 : 300000,
        depreciation: isIndia ? 250000 : 25000,
        capex: isIndia ? 400000 : 40000,
        workingCapitalChange: isIndia ? 100000 : 10000,
        taxRate: 21,
        growthRate: 15,
        discountRate: 12,
        industry: 'saas',
        ownerSalary: isIndia ? 1200000 : 80000,
        addBacks: isIndia ? 100000 : 10000,
        totalAssets: isIndia ? 4000000 : 400000,
        totalLiabilities: isIndia ? 1500000 : 150000,
      });
  }, [country, reset]);


  const onSubmit = (data: ValuationFormData) => {
    setIsLoading(true);
    setValuationResult(null);

    setTimeout(() => {
      const multipliers = industryMultipliers[data.industry as Industry];
      
      const profit = data.revenue - data.opex;

      // 1. Earnings-Based Method
      const revenueValuation = data.revenue * multipliers.revenue;
      const profitValuation = profit * multipliers.profit;
      const sde = profit + (data.ownerSalary || 0) + (data.addBacks || 0);
      const sdeValuation = sde * multipliers.sde;

      // 2. DCF Method (using UFCF)
      const futureCashFlows = [];
      let lastYearRevenue = data.revenue;
      
      for (let i = 1; i <= 5; i++) {
        lastYearRevenue *= (1 + data.growthRate / 100);
        const projectedEbit = (lastYearRevenue * (profit / data.revenue)); // Assume stable margin
        const ebitdaMinusTaxes = projectedEbit * (1 - data.taxRate / 100);
        const ufcf = ebitdaMinusTaxes + data.depreciation - data.capex - data.workingCapitalChange;
        futureCashFlows.push(ufcf);
      }
      
      const lastUFCF = futureCashFlows[futureCashFlows.length - 1];
      const perpetualGrowthRate = 0.03; // Assume 3% perpetual growth
      const terminalValue = (lastUFCF * (1 + perpetualGrowthRate)) / (data.discountRate/100 - perpetualGrowthRate);

      let dcfValuation = 0;
      if (terminalValue > 0 && isFinite(terminalValue)) {
          const allFutureValues = [...futureCashFlows, terminalValue];
          dcfValuation = allFutureValues.reduce((acc, cf, i) => {
            return acc + (cf / Math.pow(1 + data.discountRate / 100, i + 1));
          }, 0);
      } else {
        dcfValuation = futureCashFlows.reduce((acc, cf, i) => {
            return acc + (cf / Math.pow(1 + data.discountRate / 100, i + 1));
          }, 0);
      }

      // 3. Asset-Based Method
      const navValuation = (data.totalAssets || 0) - (data.totalLiabilities || 0);

      setValuationResult({
        earningsValuation: { revenue: revenueValuation, profit: profitValuation, sde: sdeValuation },
        dcfValuation: dcfValuation,
        assetValuation: { nav: navValuation }
      });
      setIsLoading(false);
    }, 1500);
  };
  
  const handleAiPrompt = async () => {
    const prompt = aiPromptRef.current?.value;
    if (!prompt) {
      toast({ title: 'AI Info', description: 'Please enter a description, e.g., "a 2-year old SaaS company with $500k revenue"' });
      return;
    }
    setIsProcessingAi(true);
    try {
        const result = await handleFinancialsGeneration(prompt);
        if (result.error) {
            throw new Error(result.error);
        }
        
        const aiData = result.data as Omit<ValuationFormData, 'industry'>;
        form.reset({
            ...form.getValues(),
            ...aiData,
        });

        toast({ title: 'AI Success', description: 'Financials populated from your prompt.'});
    } catch(e: any) {
        toast({ title: 'AI Error', description: e.message || 'Failed to generate financials from prompt.', variant: 'destructive'});
    } finally {
        setIsProcessingAi(false);
    }
  };

  const formatCurrency = (amount: number) => {
    const selectedCountry = countries.find(c => c.code === country);
    if (!selectedCountry) return amount.toString();

    return new Intl.NumberFormat(selectedCountry.locale, { 
        style: 'currency', 
        currency: selectedCountry.currency, 
        notation: 'compact',
        maximumFractionDigits: 2 
    }).format(amount);
  }

  const formatCurrencyFull = (amount: number) => {
    const selectedCountry = countries.find(c => c.code === country);
    if (!selectedCountry) return amount.toString();
    return new Intl.NumberFormat(selectedCountry.locale, {
      style: 'currency',
      currency: selectedCountry.currency,
      maximumFractionDigits: 0,
    }).format(amount);
  };

  return (
    <div className="space-y-8">
      <Alert variant="destructive">
        <AlertTriangle className="h-4 w-4" />
        <AlertTitle>Disclaimer: For Educational & Illustrative Use Only</AlertTitle>
        <AlertDescription>
          Business valuation is complex. This tool uses simplified models and should not be used for investment decisions. Always consult a qualified financial professional.
        </AlertDescription>
      </Alert>
      <div className="grid grid-cols-1 md:grid-cols-5 gap-8">
        <div className="space-y-6 md:col-span-2">
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                 <Card>
                    <CardHeader>
                        <CardTitle>Settings</CardTitle>
                    </CardHeader>
                     <CardContent>
                        <FormLabel>Currency / Region</FormLabel>
                        <Select value={country} onValueChange={(val) => setCountry(val as Country)}>
                            <SelectTrigger className="mt-1">
                              <SelectValue placeholder="Select Country" />
                            </SelectTrigger>
                            <SelectContent>
                                {countries.map(c => <SelectItem key={c.code} value={c.code}> <Globe className="inline-block mr-2 h-4 w-4"/> {c.name} ({c.currency})</SelectItem>)}
                            </SelectContent>
                        </Select>
                    </CardContent>
                </Card>
                <Card>
                     <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <Sparkles className="text-primary"/> AI Assistant
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <p className="text-sm text-muted-foreground mb-2">
                          e.g., &quot;A 3-year old profitable Shopify store doing $1M in sales&quot;
                             </p>
                        <div className="flex gap-2">
                            <Input name="ai-prompt" ref={aiPromptRef} placeholder="Describe a business..." disabled={isProcessingAi} />
                            <Button type="button" onClick={handleAiPrompt} disabled={isProcessingAi}>
                              {isProcessingAi ? <Loader2 className="animate-spin" /> : 'Generate'}
                            </Button>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                  <CardHeader><CardTitle>Financial Inputs</CardTitle></CardHeader>
                  <CardContent className="space-y-4">
                     <FormField control={form.control} name="revenue" render={({ field }) => (
                        <FormItem>
                            <FormLabel>Last 12 Months Revenue ({country})</FormLabel>
                            <FormControl><Input type="number" {...field} /></FormControl>
                            <FormMessage />
                        </FormItem>
                    )} />
                     <FormField control={form.control} name="opex" render={({ field }) => (
                        <FormItem>
                            <FormLabel>Operating Expenses (Opex, ex-Depr.) ({country})</FormLabel>
                            <FormControl><Input type="number" {...field} /></FormControl>
                            <FormMessage />
                        </FormItem>
                    )} />
                     <FormField control={form.control} name="depreciation" render={({ field }) => (
                        <FormItem>
                            <FormLabel>Depreciation & Amortization ({country})</FormLabel>
                            <FormControl><Input type="number" {...field} /></FormControl>
                            <FormMessage />
                        </FormItem>
                    )} />
                     <FormField control={form.control} name="capex" render={({ field }) => (
                        <FormItem>
                            <FormLabel>Capital Expenditures (CAPEX) ({country})</FormLabel>
                            <FormControl><Input type="number" {...field} /></FormControl>
                            <FormMessage />
                        </FormItem>
                    )} />
                     <FormField control={form.control} name="workingCapitalChange" render={({ field }) => (
                        <FormItem>
                            <FormLabel>Annual Change in Working Capital ({country})</FormLabel>
                            <FormControl><Input type="number" {...field} /></FormControl>
                            <FormMessage />
                        </FormItem>
                    )} />
                     <FormField control={form.control} name="taxRate" render={({ field }) => (
                        <FormItem>
                            <FormLabel>Corporate Tax Rate: {field.value}%</FormLabel>
                            <FormControl><Slider min={0} max={100} step={1} onValueChange={(v) => field.onChange(v[0])} defaultValue={[field.value]} /></FormControl>
                            <FormMessage />
                        </FormItem>
                    )} />

                    <FormField control={form.control} name="industry" render={({ field }) => (
                      <FormItem>
                        <FormLabel>Industry</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger><SelectValue placeholder="Select an industry" /></SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            <SelectItem value="saas">SaaS / Technology</SelectItem>
                            <SelectItem value="ecommerce">E-commerce / Retail</SelectItem>
                            <SelectItem value="service">Service-Based Business</SelectItem>
                            <SelectItem value="manufacturing">Manufacturing</SelectItem>
                            <SelectItem value="biotech">Biotech / Pharma</SelectItem>
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )} />
                     <FormField control={form.control} name="growthRate" render={({ field }) => (
                        <FormItem>
                            <FormLabel>Projected Annual Growth Rate: {field.value}%</FormLabel>
