              <Input id="file-upload" type="file" className="hidden" accept=".csv, .xls, .xlsx" onChange={handleFileChange} />
            </label>
             <div className="flex justify-between mt-6">
                <Button variant="outline" onClick={() => setStep('method')}><ArrowLeft className="mr-2 h-4 w-4" /> Back</Button>
            </div>
          </div>
        );

    case 'connect':
        return (
            <div>
                 <CardHeader className="p-0 mb-4">
                    <CardTitle>Connect an Exchange or Wallet</CardTitle>
                    <CardDescription>
                    Select a service to sync your transactions automatically. This provides read-only access.
                    </CardDescription>
                </CardHeader>

                <h3 className="font-semibold mb-2 mt-4">Exchanges</h3>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                    {exchanges.map(ex => (
                        <Button key={ex} variant="outline" className="justify-start gap-2" disabled><Building className="h-4 w-4 text-muted-foreground"/> {ex}</Button>
                    ))}
                </div>
                <h3 className="font-semibold mb-2 mt-6">Wallets</h3>
                 <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                    {wallets.map(w => (
                         <Button key={w} variant="outline" className="justify-start gap-2" disabled><Wallet className="h-4 w-4 text-muted-foreground"/> {w}</Button>
                    ))}
                </div>
                 <Alert className="mt-4">
                    <Info className="h-4 w-4" />
                    <AlertTitle>Feature Coming Soon</AlertTitle>
                    <AlertDescription>
                        Automatic exchange and wallet sync is under development. Please use the CSV upload or manual entry for now.
                    </AlertDescription>
                </Alert>
                 <div className="flex justify-between mt-6">
                    <Button variant="outline" onClick={() => setStep('method')}><ArrowLeft className="mr-2 h-4 w-4" /> Back</Button>
                    <Button disabled>Connect <ArrowRight className="ml-2 h-4 w-4" /></Button>
                </div>
            </div>
        );

    case 'manual':
        return (
            <div className="space-y-6">
                <CardHeader className="p-0">
                    <CardTitle>Manage Transactions</CardTitle>
                    <CardDescription>Add, edit, or delete your crypto transactions below. You can switch to file upload anytime.</CardDescription>
                </CardHeader>
                {fields.length > 0 ? (
                  <div className="overflow-x-auto border rounded-lg">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead className="w-[120px]">Type</TableHead>
                                <TableHead>Asset</TableHead>
                                <TableHead>Quantity</TableHead>
                                <TableHead>Price</TableHead>
                                <TableHead>Date</TableHead>
                                <TableHead className="w-[50px]"></TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {fields.map((field, index) => (
                                <TableRow key={field.id}>
                                    <TableCell><FormField control={form.control} name={`transactions.${index}.type`} render={({ field }) => (<Select onValueChange={field.onChange} defaultValue={field.value}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="buy">Buy</SelectItem><SelectItem value="sell">Sell</SelectItem></SelectContent></Select>)} /></TableCell>
                                    <TableCell><FormField control={form.control} name={`transactions.${index}.asset`} render={({ field }) => (<Input {...field} placeholder="BTC"/>)} /></TableCell>
                                    <TableCell><FormField control={form.control} name={`transactions.${index}.quantity`} render={({ field }) => (<Input type="number" {...field} />)} /></TableCell>
                                    <TableCell><FormField control={form.control} name={`transactions.${index}.price`} render={({ field }) => (<Input type="number" {...field} />)} /></TableCell>
                                    <TableCell><FormField control={form.control} name={`transactions.${index}.date`} render={({ field }) => (<Input type="date" {...field} />)} /></TableCell>
                                    <TableCell><Button variant="ghost" size="icon" onClick={() => remove(index)}><Trash2 className="h-4 w-4 text-muted-foreground" /></Button></TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                  </div>
                ) : (
                  <div className="text-center py-12 text-muted-foreground border-2 border-dashed rounded-lg">
                    <p>No transactions added yet.</p>
                    <p className="text-sm">Add one below or go back to upload a file.</p>
                  </div>
                )}
                <Button type="button" variant="outline" onClick={() => append({ type: 'buy', asset: '', quantity: 0, price: 0, date: new Date().toISOString().split('T')[0] })}><PlusCircle className="mr-2 h-4 w-4" />Add Transaction</Button>
                <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-4 border-t">
                    <Button variant="outline" onClick={() => setStep('method')}><ArrowLeft className="mr-2 h-4 w-4" /> Change Import Method</Button>
                    <Button onClick={() => setStep('calculate')} disabled={fields.length === 0}><Calculator className="mr-2 h-4 w-4"/>Calculate Taxes</Button>
                </div>
            </div>
        )
      case 'calculate':
        return (
            <div className="space-y-6">
                <CardHeader className="p-0">
                    <CardTitle>Select Your Tax Country</CardTitle>
                    <CardDescription>Choose your country of residence for tax purposes to apply the correct rules.</CardDescription>
                </CardHeader>
                <Select onValueChange={(val) => handleCalculateTaxes(val as Country)}>
                    <SelectTrigger className="w-full">
                        <SelectValue placeholder="Select a country..." />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectGroup>
                            {countries.map(c => <SelectItem key={c.code} value={c.code}><Globe className="inline-block mr-2 h-4 w-4"/>{c.name}</SelectItem>)}
                        </SelectGroup>
                    </SelectContent>
                </Select>
                 <div className="flex justify-start mt-6">
                    <Button variant="outline" onClick={() => setStep('manual')}><ArrowLeft className="mr-2 h-4 w-4" /> Back to Transactions</Button>
                </div>
            </div>
        )

      default:
        return <p>This step is under construction.</p>;
    }
  };

  return (
    <div className="space-y-8">
      <Alert variant="destructive">
        <AlertTriangle className="h-4 w-4" />
        <AlertTitle>Disclaimer: For Educational & Illustrative Use Only</AlertTitle>
        <AlertDescription>
          This is a simplified tool using the FIFO method. It does not account for all transaction types, fees, or specific tax laws (like the UK&apos;s 'share pooling&apos; rule). **Do not use for official tax filing.** Always consult a qualified tax professional.
                  </AlertDescription>
      </Alert>
      
      <Form {...form}>
        <form onSubmit={(e) => e.preventDefault()} className="space-y-6">
          <Card className="w-full max-w-4xl mx-auto">
            <CardContent className="p-6 md:p-8">
              {renderStepContent()}
            </CardContent>
          </Card>
        </form>
      </Form>
    </div>
  );
}

"use client";

import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Loader2, Landmark, Building, University } from 'lucide-react';

const formSchema = z.object({
  loanAmount: z.number().min(1000, "Must be at least 1,000").max(10000000, "Must be at most 1,00,00,000 / 1,000,000"),
  annualIncome: z.number().min(10000, "Must be at least 10,000").max(50000000, "Must be at most 5,00,00,000 / 5,000,000"),
  creditScore: z.number().min(300, "Invalid score").max(850, "Invalid score"), // US max is 850
  loanTenure: z.number().min(1, "Must be at least 1 year").max(30, "Must be at most 30 years"),
});

type LoanFormData = z.infer<typeof formSchema>;

interface Bank {
    name: string;
    logo: React.ReactNode;
    baseRate: number;
}

interface LoanOffer {
    bankName: string;
    interestRate: number;
    monthlyPayment: number;
    totalPayment: number;
    bankLogo: React.ReactNode;
}

const indianBanks: Bank[] = [
    { name: 'HDFC Bank', logo: <Building className="text-blue-600" />, baseRate: 10.5 },
    { name: 'State Bank of India', logo: <Landmark className="text-blue-800" />, baseRate: 10.2 },
    { name: 'ICICI Bank', logo: <Building className="text-orange-500" />, baseRate: 10.8 },
    { name: 'Axis Bank', logo: <Building className="text-purple-700" />, baseRate: 11.0 },
    { name: 'Kotak Mahindra Bank', logo: <Building className="text-red-600" />, baseRate: 10.7 }
];

const usBanks: Bank[] = [
    { name: 'Chase Bank', logo: <Landmark className="text-blue-700" />, baseRate: 7.2 },
    { name: 'Bank of America', logo: <University className="text-red-700" />, baseRate: 7.0 },
    { name: 'Wells Fargo', logo: <Landmark className="text-red-500" />, baseRate: 7.5 },
    { name: 'Citibank', logo: <University className="text-blue-500" />, baseRate: 7.3 },
    { name: 'U.S. Bank', logo: <Landmark className="text-indigo-600" />, baseRate: 7.8 }
];

type Country = 'IN' | 'US';

export function GlobalLoanOptimizer() {
    const [loanOffers, setLoanOffers] = useState<LoanOffer[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [country, setCountry] = useState<Country>('US');

    useEffect(() => {
        try {
            const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
            if (timeZone.startsWith('Asia/')) {
                setCountry('IN');
            } else {
                setCountry('US');
            }
        } catch (error) {
            console.error("Could not detect timezone, defaulting to US.");
            setCountry('US');
        }
    }, []);

    const isIndia = country === 'IN';
    const banks = isIndia ? indianBanks : usBanks;

    const form = useForm<LoanFormData>({
        resolver: zodResolver(formSchema),
        defaultValues: {
            loanAmount: isIndia ? 500000 : 50000,
            annualIncome: isIndia ? 1000000 : 80000,
            creditScore: 750,
            loanTenure: 5
        },
        mode: 'onChange',
    });
    
    const { reset } = form;
    useEffect(() => {
        reset({
            loanAmount: isIndia ? 500000 : 50000,
            annualIncome: isIndia ? 1000000 : 80000,
            creditScore: 750,
            loanTenure: 5
        });
    }, [country, reset, isIndia]);


    const onSubmit = (data: LoanFormData) => {
        setIsLoading(true);
        setLoanOffers([]);
        
        setTimeout(() => {
            const offers: LoanOffer[] = banks.map(bank => {
                let rate = bank.baseRate;

                const creditScoreFactor = ((data.creditScore - 700) / 150) * (isIndia ? 2.0 : 1.5);
                rate -= creditScoreFactor;

                const incomeToLoanRatio = data.annualIncome / data.loanAmount;
                if (incomeToLoanRatio > (isIndia ? 4 : 3)) {
                    rate -= (isIndia ? 0.75 : 0.5);
                } else if (incomeToLoanRatio < 2) {
                    rate += (isIndia ? 0.75 : 0.5);
                }

                rate += (Math.random() - 0.5) * 0.4; 
                
                const finalRate = Math.max(isIndia ? 8.5 : 5.0, Math.min(isIndia ? 18.0 : 15.0, rate));
                
                const monthlyRate = finalRate / 100 / 12;
                const numberOfPayments = data.loanTenure * 12;
                const monthlyPayment = (data.loanAmount * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -numberOfPayments));
                const totalPayment = monthlyPayment * numberOfPayments;

                return {
                    bankName: bank.name,
                    interestRate: parseFloat(finalRate.toFixed(2)),
                    monthlyPayment: parseFloat(monthlyPayment.toFixed(2)),
                    totalPayment: parseFloat(totalPayment.toFixed(2)),
                    bankLogo: bank.logo,
                };
            }).sort((a,b) => a.interestRate - b.interestRate);

            setLoanOffers(offers);
            setIsLoading(false);
        }, 1500);
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat(isIndia ? 'en-IN' : 'en-US', { 
            style: 'currency', 
            currency: isIndia ? 'INR' : 'USD', 
            maximumFractionDigits: 0 
        }).format(amount);
    }
    
    return (
        <div className="space-y-8">
           <p className="text-muted-foreground">
                Enter your financial details to see simulated loan offers from banks in your region. This tool helps you understand how factors like credit score and income can affect loan terms.
           </p>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <FormField control={form.control} name="loanAmount" render={({ field }) => (
                            <FormItem>
                                <FormLabel>Loan Amount: {formatCurrency(field.value)}</FormLabel>
                                <FormControl>
                                    <Slider min={isIndia ? 50000 : 5000} max={isIndia ? 10000000 : 500000} step={isIndia ? 10000 : 1000} onValueChange={(vals) => field.onChange(vals[0])} defaultValue={[field.value]} />
                                </FormControl>
                                <FormMessage />
                            </FormItem>
                        )} />
                        <FormField control={form.control} name="annualIncome" render={({ field }) => (
                             <FormItem>
                                <FormLabel>Annual Income: {formatCurrency(field.value)}</FormLabel>
                                <FormControl>
                                    <Slider min={isIndia ? 100000 : 20000} max={isIndia ? 50000000 : 1000000} step={isIndia ? 25000 : 5000} onValueChange={(vals) => field.onChange(vals[0])} defaultValue={[field.value]} />
                                </FormControl>
                                <FormMessage />
                            </FormItem>
                        )} />
                        <FormField control={form.control} name="creditScore" render={({ field }) => (
                            <FormItem>
                                <FormLabel>Credit Score: {field.value}</FormLabel>
                                <FormControl>
                                    <Slider min={300} max={850} step={1} onValueChange={(vals) => field.onChange(vals[0])} defaultValue={[field.value]} />
                                </FormControl>
                                <FormMessage />
                            </FormItem>
                        )} />
                        <FormField control={form.control} name="loanTenure" render={({ field }) => (
                            <FormItem>
                                <FormLabel>Loan Tenure: {field.value} years</FormLabel>
                                <FormControl>
                                    <Slider min={1} max={30} step={1} onValueChange={(vals) => field.onChange(vals[0])} defaultValue={[field.value]} />
                                </FormControl>
                                <FormMessage />
                            </FormItem>
                        )} />
                    </div>
                     <Button type="submit" className="w-full md:w-auto" disabled={isLoading}>
                        {isLoading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin"/> Processing...</> : 'Find Best Loans'}
                    </Button>
                </form>
            </Form>

            {isLoading && (
                <div className="flex items-center justify-center text-center p-8">
                    <Loader2 className="mr-4 h-8 w-8 animate-spin text-primary" />
                    <p className="text-muted-foreground">Analyzing offers from {isIndia ? 'Indian' : 'US'} lenders...</p>
                </div>
            )}

            {loanOffers.length > 0 && !isLoading && (
                 <Card>
                    <CardHeader>
                        <CardTitle>Simulated Loan Offers ({country})</CardTitle>
                        <CardDescription>
                            Based on your inputs, here are some estimated loan offers. These are for informational purposes only.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Bank</TableHead>
                                    <TableHead className="text-right">Interest Rate</TableHead>
                                    <TableHead className="text-right">Monthly Payment</TableHead>
                                    <TableHead className="text-right">Total Payment</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {loanOffers.map((offer) => (
                                    <TableRow key={offer.bankName}>
                                        <TableCell className="font-medium flex items-center gap-2">
                                            {offer.bankLogo}
                                            {offer.bankName}
                                        </TableCell>
                                        <TableCell className="text-right">{offer.interestRate.toFixed(2)}%</TableCell>
                                        <TableCell className="text-right">{formatCurrency(offer.monthlyPayment)}</TableCell>
                                        <TableCell className="text-right">{formatCurrency(offer.totalPayment)}</TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </CardContent>
                </Card>
            )}
        </div>
    );

}

"use client";
import { useState } from 'react';
import imageCompression from 'browser-image-compression';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Loader2, UploadCloud, Download, Image as ImageIcon } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';

interface CompressedResult {
  file: File;
  url: string;
  originalSize: number;
  compressedSize: number;
}

export function ImageCompressor() {
  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [originalUrl, setOriginalUrl] = useState<string>('');
  const [compressedResult, setCompressedResult] = useState<CompressedResult | null>(null);
  const [isCompressing, setIsCompressing] = useState<boolean>(false);
  const [error, setError] = useState<string>('');
  const { toast } = useToast();

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.type.startsWith('image/')) {
        setOriginalFile(file);
        setOriginalUrl(URL.createObjectURL(file));
        setCompressedResult(null);
        setError('');
      } else {
        setError('Please select a valid image file.');
        toast({
            title: 'Invalid File',
            description: 'Please select a valid image file.',
            variant: 'destructive',
        });
        setOriginalFile(null);
        setOriginalUrl('');
      }
    }
  };

  const handleCompress = async () => {
    if (!originalFile) {
      setError('Please select an image first.');
      toast({
        title: 'No Image Selected',
        description: 'Please select an image first.',
        variant: 'destructive',
      });
      return;
    }
    setIsCompressing(true);
    setError('');
    setCompressedResult(null);

    const options = {
      maxSizeMB: 1,
      maxWidthOrHeight: 1920,
      useWebWorker: true,
    };

    try {
      const compressedFile = await imageCompression(originalFile, options);
      const compressedUrl = URL.createObjectURL(compressedFile);

      setCompressedResult({
        file: compressedFile,
        url: compressedUrl,
        originalSize: originalFile.size,
        compressedSize: compressedFile.size,
      });
       toast({
        title: 'Compression Successful',
        description: 'Your image has been compressed.',
      });
    } catch (compressionError) {
      console.error('Compression error:', compressionError);
      setError('Failed to compress image. Please try a different file.');
      toast({
        title: 'Compression Failed',
        description: 'Failed to compress image. Please try a different file.',
        variant: 'destructive',
      });
    } finally {
      setIsCompressing(false);
    }
  };

  const handleDownload = () => {
    if (compressedResult) {
      const link = document.createElement('a');
      link.href = compressedResult.url;
      link.download = `compressed_${compressedResult.file.name}`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  const formatBytes = (bytes: number, decimals = 2) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const dm = decimals < 0 ? 0 : decimals;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
  };

  return (
    <div className="w-full max-w-4xl mx-auto space-y-8">
        <div className="space-y-6">
            <div className="flex flex-col items-center justify-center w-full">
              <label htmlFor="image-upload" className="flex flex-col items-center justify-center w-full h-48 sm:h-64 border-2 border-dashed rounded-lg cursor-pointer bg-muted hover:bg-background transition-colors">
                <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                  <UploadCloud className="w-10 h-10 mb-3 text-muted-foreground" />
                  {originalFile ? (
                    <p className="font-semibold text-primary break-all px-2">{originalFile.name}</p>
                  ) : (
                    <>
                      <p className="mb-2 text-sm text-muted-foreground"><span className="font-semibold">Click to upload</span> or drag and drop</p>
                      <p className="text-xs text-muted-foreground">PNG, JPG, WEBP, GIF</p>
                    </>
                  )}
                </div>
                <Input id="image-upload" type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
              </label>
            </div>

            {error && <p className="text-sm font-medium text-destructive text-center">{error}</p>}

            <Button onClick={handleCompress} disabled={!originalFile || isCompressing} className="w-full h-12 text-lg">
              {isCompressing ? (
                <>
                  <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                  Compressing...
                </>
              ) : 'Compress Image'}
            </Button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
          <div className="space-y-4 text-center">
            <h3 className="text-xl font-semibold">Original Image</h3>
            <div className="bg-muted aspect-video rounded-lg flex items-center justify-center overflow-hidden border">
              {originalUrl ? <img src={originalUrl} alt="Original" className="max-h-full max-w-full object-contain" /> : <ImageIcon className="h-16 w-16 text-muted-foreground" />}
            </div>
            {originalFile && <p className="text-muted-foreground">Size: {formatBytes(originalFile.size)}</p>}
          </div>

          <div className="space-y-4 text-center">
            <h3 className="text-xl font-semibold">Compressed Image</h3>
            <div className="bg-muted aspect-video rounded-lg flex items-center justify-center overflow-hidden border">
              {isCompressing && <Loader2 className="h-12 w-12 animate-spin text-primary" />}
              {!isCompressing && compressedResult ? <img src={compressedResult.url} alt="Compressed" className="max-h-full max-w-full object-contain" /> : !isCompressing && <ImageIcon className="h-16 w-16 text-muted-foreground" />}
            </div>
            {compressedResult && (
              <div className="space-y-4">
                <p className="text-muted-foreground">
                  New Size: {formatBytes(compressedResult.compressedSize)} | Reduction: {(((compressedResult.originalSize - compressedResult.compressedSize) / compressedResult.originalSize) * 100).toFixed(2)}%
                </p>
                <Button onClick={handleDownload} className="w-full">
                  <Download className="mr-2 h-5 w-5" />
                  Download Compressed Image
                </Button>
              </div>
            )}
          </div>
        </div>
    </div>
  );
}

