      const reader = new FileReader();
      reader.onload = (e) => {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const json = XLSX.utils.sheet_to_json(worksheet);
        setExcelToJsonOutput(JSON.stringify(json, null, 2));
        toast({ title: 'Excel file processed successfully!' });
      };
      reader.readAsBinaryString(file);
    }
  };

  const handleFetchUrl = async () => {
    const url = (document.getElementById('url-input') as HTMLInputElement)
      .value;
    if (!url) {
      toast({
        title: 'URL is empty',
        description: 'Please enter a URL to fetch JSON from.',
        variant: 'destructive',
      });
      return;
    }

    setIsLoading(true);
    try {
      // Note: This fetch is subject to CORS policies of the destination server.
      // We can suggest a server-side proxy for a more robust solution.
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      const jsonString = JSON.stringify(data, null, 2);
      setJsonInput(jsonString);
      if(activeTab === 'json-to-excel') {
        parseAndDisplayJson(jsonString);
      }
    } catch (e: any) {
      toast({
        title: 'Failed to fetch URL',
        description: e.message || 'Could not retrieve data. This may be due to browser CORS restrictions.',
        variant: 'destructive',
      });
      setError('Could not retrieve data from the URL. This may be due to browser CORS restrictions.');
    } finally {
      setIsLoading(false);
    }
  };

  const flattenObject = (obj: any, prefix = '', style: FlattenStyle = 'dot'): Record<string, any> => {
    const separator = style === 'dot' ? '.' : '_';
    return Object.keys(obj).reduce((acc, k) => {
        const pre = prefix.length ? prefix + separator : '';
        const key = pre + k;
        if (obj[k] && typeof obj[k] === 'object' && !Array.isArray(obj[k])) {
            Object.assign(acc, flattenObject(obj[k], key, style));
        } else {
            acc[key] = obj[k];
        }
        return acc;
    }, {} as Record<string, any>);
  };

  const flattenJson = (data: any, style: FlattenStyle): Record<string, any>[] => {
    const array = Array.isArray(data) ? data : [data];
    return array.map(item => flattenObject(item, '', style));
  };


  const parseAndDisplayJson = (jsonString: string) => {
    if (!jsonString.trim()) {
      setJsonInput('');
      setTableData(null);
      setAllKeys([]);
      setSelectedKeys({});
      setError(null);
      return;
    }

    try {
      const data = JSON.parse(jsonString);
      setError(null);

      const flattenedData = flattenJson(data, flattenStyle);
      if (flattenedData.length === 0) {
        setTableData(null);
        return;
      }

      const headers = Array.from(new Set(flattenedData.flatMap(Object.keys))).sort();
      setAllKeys(headers);

      const initialSelectedKeys: Record<string, boolean> = {};
      headers.forEach(h => initialSelectedKeys[h] = true);
      setSelectedKeys(initialSelectedKeys);

    } catch (e) {
      setError('Invalid JSON format. Please check your input.');
      setTableData(null);
      setAllKeys([]);
      setSelectedKeys({});
    }
  };

  useEffect(() => {
    if (jsonInput && activeTab === 'json-to-excel') {
        parseAndDisplayJson(jsonInput);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flattenStyle, activeTab]);

  const filteredTableData = useMemo((): TableData | null => {
    if (!jsonInput || error) return null;
    try {
        const data = JSON.parse(jsonInput);
        const flattenedData = flattenJson(data, flattenStyle);
        const activeKeys = allKeys.filter(k => selectedKeys[k]);

        const rows = flattenedData.map(item =>
            activeKeys.map(header => {
                const value = item[header];
                if (typeof value === 'object' && value !== null) {
                    return JSON.stringify(value);
                }
                return value === undefined ? null : value;
            })
        );

        return { headers: activeKeys, rows };
    } catch {
        return null;
    }
  }, [jsonInput, allKeys, selectedKeys, flattenStyle, error]);

  const handleDownload = (format: 'xlsx' | 'csv') => {
    if (!filteredTableData) {
      toast({
        title: 'No data to download',
        description: 'Please provide valid JSON first.',
        variant: 'destructive',
      });
      return;
    }

    const worksheetData = [
      filteredTableData.headers,
      ...filteredTableData.rows.map(row => row.map(cell => (cell === null ? '' : cell))),
    ];

    if (format === 'xlsx') {
      const wb = XLSX.utils.book_new();
      const ws = XLSX.utils.aoa_to_sheet(worksheetData);
      XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
      XLSX.writeFile(wb, 'converted_data.xlsx');
    } else if (format === 'csv') {
      const csv = Papa.unparse(worksheetData);
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.setAttribute('download', 'converted_data.csv');
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: "Copied to clipboard!" });
  };

  const beautifyJson = () => {
    try {
      const parsed = JSON.parse(jsonInput);
      setJsonInput(JSON.stringify(parsed, null, 2));
      setError(null);
    } catch (e) {
      setError("Cannot format invalid JSON.");
    }
  }

  const parsedJsonForTree = useMemo(() => {
    try {
        return JSON.parse(jsonInput);
    } catch {
        return null;
    }
  }, [jsonInput]);

  return (
    <div className="space-y-4">
        <Tabs defaultValue="json-to-excel" onValueChange={setActiveTab} className="w-full">
            <TabsList className="grid w-full grid-cols-4">
                <TabsTrigger value="json-to-excel"><ChevronsRightLeft className="mr-2"/>JSON to Excel/CSV</TabsTrigger>
                <TabsTrigger value="excel-to-json"><ChevronsRightLeft className="mr-2"/>Excel to JSON</TabsTrigger>
                <TabsTrigger value="tree-viewer"><ListTree className="mr-2"/>Tree Viewer</TabsTrigger>
                <TabsTrigger value="formatter"><PenSquare className="mr-2"/>Formatter</TabsTrigger>
            </TabsList>

            <TabsContent value="json-to-excel">
                <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
                    {/* Left Column */}
                    <div className="lg:col-span-2 space-y-6">
                       <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center justify-between">
                            <div className="flex items-center gap-2"><FileJson /> JSON Input</div>
                             <Button variant="ghost" size="sm" onClick={clearAll}><Trash2 className="mr-2"/>Clear</Button>
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            <Tabs defaultValue="paste">
                            <TabsList className="grid w-full grid-cols-3">
                                <TabsTrigger value="paste">Paste</TabsTrigger>
                                <TabsTrigger value="upload">Upload</TabsTrigger>
                                <TabsTrigger value="url">From URL</TabsTrigger>
                            </TabsList>
                            <TabsContent value="paste" className="mt-4">
                                <Textarea
                                placeholder='{ "message": "Paste your JSON here" }'
                                value={jsonInput}
                                onChange={handleJsonInputChange}
                                className="min-h-[200px] font-mono text-sm"
                                />
                            </TabsContent>
                            <TabsContent value="upload" className="mt-4">
                                <label
                                htmlFor="file-upload-json"
                                className="flex flex-col items-center justify-center w-full h-48 border-2 border-dashed rounded-lg cursor-pointer bg-muted hover:bg-background transition-colors"
                                >
                                <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                                    <UploadCloud className="w-10 h-10 mb-3 text-muted-foreground" />
                                    <p className="mb-2 text-sm text-muted-foreground">
                                    <span className="font-semibold">Click to upload</span> or
                                    drag & drop
                                    </p>
                                    <p className="text-xs text-muted-foreground">.JSON or .TXT file</p>
                                </div>
                                <Input
                                    id="file-upload-json"
                                    type="file"
                                    className="hidden"
                                    accept=".json,.txt"
                                    onChange={handleFileChange}
                                />
                                </label>
                            </TabsContent>
                            <TabsContent value="url" className="mt-4 space-y-4">
                                <Label htmlFor="url-input">JSON URL</Label>
                                <div className="flex gap-2">
                                <Input
                                    id="url-input"
                                    type="url"
                                    placeholder="https://api.example.com/data.json"
                                />
                                <Button onClick={handleFetchUrl} disabled={isLoading}>
                                    {isLoading ? (
                                    <Loader2 className="animate-spin" />
                                    ) : (
                                    'Fetch'
                                    )}
                                </Button>
                                </div>
                            </TabsContent>
                            </Tabs>

                            {error && (
                            <Alert variant="destructive" className="mt-4">
                                <XCircle className="h-4 w-4" />
                                <AlertTitle>Validation Error</AlertTitle>
                                <AlertDescription>{error}</AlertDescription>
                            </Alert>
                            )}
                            {!error && jsonInput && (
                            <Alert variant="default" className="mt-4 border-green-500/50">
                                <CheckCircle className="h-4 w-4 text-green-500"/>
                                <AlertTitle>JSON is Valid</AlertTitle>
                            </Alert>
                            )}
                        </CardContent>
                        </Card>

                        <Card>
                            <CardHeader>
                                <CardTitle className="flex items-center gap-2"><Settings/> Options</CardTitle>
                            </CardHeader>
                            <CardContent className="space-y-6">
                                <div>
                                    <Label>Flattening Style</Label>
                                    <RadioGroup value={flattenStyle} onValueChange={(v) => setFlattenStyle(v as FlattenStyle)} className="mt-2">
                                        <div className="flex items-center space-x-2">
                                            <RadioGroupItem value="dot" id="r_dot" />
                                            <Label htmlFor="r_dot">Dot Notation (e.g. user.name)</Label>
                                        </div>
                                         <div className="flex items-center space-x-2">
                                            <RadioGroupItem value="underscore" id="r_underscore" />
                                            <Label htmlFor="r_underscore">Underscore Notation (e.g. user_name)</Label>
                                        </div>
                                    </RadioGroup>
                                </div>
                                {allKeys.length > 0 && (
                                    <div>
                                        <Label>Select Columns ({Object.values(selectedKeys).filter(Boolean).length} / {allKeys.length})</Label>
                                        <ScrollArea className="h-40 w-full rounded-md border p-4 mt-2">
                                            <div className="space-y-2">
                                                {allKeys.map(key => (
                                                    <div key={key} className="flex items-center space-x-2">
                                                        <Checkbox
                                                            id={key}
                                                            checked={selectedKeys[key]}
                                                            onCheckedChange={(checked) => {
                                                                setSelectedKeys(prev => ({...prev, [key]: !!checked}))
                                                            }}
                                                        />
                                                        <label htmlFor={key} className="text-sm font-mono leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
                                                            {key}
                                                        </label>
                                                    </div>
                                                ))}
                                            </div>
                                        </ScrollArea>
                                    </div>
                                )}
                            </CardContent>
                        </Card>
                    </div>

                    {/* Right Column */}
                    <div className="lg:col-span-3 space-y-4">
                        <Card>
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                            <TableIcon /> Table Preview
                            </CardTitle>
                            <CardDescription>
                            Your JSON data displayed as a table.
                            </CardDescription>
                        </CardHeader>
                        <CardContent>
                            {filteredTableData ? (
                            <div className="overflow-auto border rounded-lg max-h-[500px]">
                                <Table>
                                <TableHeader className="sticky top-0 bg-muted z-10">
                                    <TableRow>
                                    {filteredTableData.headers.map(header => (
                                        <TableHead key={header}>{header}</TableHead>
                                    ))}
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {filteredTableData.rows.map((row, rowIndex) => (
                                    <TableRow key={rowIndex}>
                                        {row.map((cell, cellIndex) => (
                                        <TableCell key={cellIndex} className="whitespace-nowrap font-mono text-xs">
                                            {cell === null ? (
                                            <span className="text-muted-foreground">
                                                null
                                            </span>
                                            ) : (
                                            String(cell)
                                            )}
                                        </TableCell>
                                        ))}
                                    </TableRow>
                                    ))}
                                </TableBody>
                                </Table>
                            </div>
                            ) : (
                            <div className="text-center py-12 text-muted-foreground border-2 border-dashed rounded-lg h-96 flex items-center justify-center">
                                <p>Provide valid JSON to see the table preview.</p>
                            </div>
                            )}
                            <div className="flex flex-wrap gap-2 mt-4">
                            <Button
                                onClick={() => handleDownload('xlsx')}
                                disabled={!filteredTableData}
                            >
                                <FileSpreadsheet className="mr-2" /> Download .xlsx
                            </Button>
                            <Button
                                onClick={() => handleDownload('csv')}
                                disabled={!filteredTableData}
                                variant="secondary"
                            >
                                <FileText className="mr-2" /> Download .csv
                            </Button>
                            <Button
                                onClick={() => copyToClipboard(Papa.unparse( [ filteredTableData?.headers ?? [], ...filteredTableData?.rows ?? []], { delimiter: "\t" }))}
                                disabled={!filteredTableData}
                                variant="outline"
                            >
                                <Copy className="mr-2"/> Copy Table
                            </Button>
                            </div>
                        </CardContent>
                        </Card>
                    </div>
                </div>
            </TabsContent>

            <TabsContent value="excel-to-json">
                 <Card>
                    <CardHeader>
                        <CardTitle>Excel/CSV to JSON Converter</CardTitle>
                        <CardDescription>Upload your spreadsheet to convert it into JSON format.</CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                         <label
                            htmlFor="file-upload-excel"
                            className="flex flex-col items-center justify-center w-full h-48 border-2 border-dashed rounded-lg cursor-pointer bg-muted hover:bg-background transition-colors"
                            >
                            <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                                <UploadCloud className="w-10 h-10 mb-3 text-muted-foreground" />
                                <p className="mb-2 text-sm text-muted-foreground"><span className="font-semibold">Click to upload</span> or drag & drop</p>
                                <p className="text-xs text-muted-foreground">.XLSX or .CSV file</p>
                            </div>
                            <Input id="file-upload-excel" type="file" className="hidden" accept=".xlsx,.csv" onChange={handleExcelFileChange} />
                        </label>
                        {excelToJsonOutput && (
                             <div className="relative">
                                <Textarea
                                    value={excelToJsonOutput}
                                    readOnly
                                    className="min-h-[300px] font-mono text-sm bg-muted"
                                />
                                <Button variant="ghost" size="icon" className="absolute top-2 right-2" onClick={() => copyToClipboard(excelToJsonOutput)}><Copy/></Button>
                            </div>
                        )}
                    </CardContent>
                 </Card>
            </TabsContent>

            <TabsContent value="tree-viewer">
                 <Card>
                    <CardHeader>
                        <CardTitle>JSON Tree Viewer</CardTitle>
                        <CardDescription>Explore your JSON data in a collapsible tree structure.</CardDescription>
                    </CardHeader>
                    <CardContent>
                        <Textarea
                            placeholder='{ "message": "Paste your JSON here to view it as a tree" }'
                            value={jsonInput}
                            onChange={handleJsonInputChange}
                            className="min-h-[150px] font-mono text-sm mb-4"
                        />
                         {parsedJsonForTree ? (
                             <ScrollArea className="h-96 w-full rounded-md border p-4">
                                <JsonTree data={parsedJsonForTree} />
                            </ScrollArea>
                         ) : (
                            <div className="text-center py-12 text-muted-foreground border-2 border-dashed rounded-lg h-96 flex items-center justify-center">
                                <p>Provide valid JSON to see the tree view.</p>
                            </div>
                         )}
                    </CardContent>
                 </Card>
            </TabsContent>

            <TabsContent value="formatter">
                 <Card>
                    <CardHeader>
                        <CardTitle>JSON Formatter & Beautifier</CardTitle>
                        <CardDescription>Clean up and format your JSON to make it readable.</CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                         <Textarea
                            placeholder='{"messy":"json"}'
                            value={jsonInput}
                            onChange={handleJsonInputChange}
                            className="min-h-[400px] font-mono text-sm"
                        />
                        <Button onClick={beautifyJson}><RefreshCw className="mr-2"/>Beautify JSON</Button>
                         {error && (
                            <Alert variant="destructive" className="mt-4">
                                <XCircle className="h-4 w-4" />
                                <AlertTitle>Validation Error</AlertTitle>
                                <AlertDescription>{error}</AlertDescription>
                            </Alert>
                        )}
                    </CardContent>
                 </Card>
            </TabsContent>
        </Tabs>
    </div>
  );
}

"use client";

import { useState, useEffect } from 'react';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { CheckCircle2, XCircle, Shield, Info } from 'lucide-react';
import { jwtVerify, decodeJwt } from 'jose';

// Helper to format JSON with indentation
const formatJson = (obj: any) => JSON.stringify(obj, null, 2);

export function JwtDecoderValidator() {
  const [encodedToken, setEncodedToken] = useState('');
  const [secretKey, setSecretKey] = useState('');
  const [header, setHeader] = useState<object | null>(null);
  const [payload, setPayload] = useState<Record<string, any> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [verificationStatus, setVerificationStatus] = useState<'idle' | 'valid' | 'invalid' | 'error'>();
  const [verificationError, setVerificationError] = useState<string | null>(null);

  // Function to decode header/payload without validation
  const decodeToken = (token: string) => {
    try {
      setError(null);
      const decodedHeader = decodeJwt(token);
      
      const parts = token.split('.');
      if (parts.length !== 3) {
        throw new Error('Invalid JWT structure. The token must have three parts separated by dots.');
      }
      const decodedPayload = JSON.parse(new TextDecoder().decode(Buffer.from(parts[1], 'base64')));

      setHeader(decodedHeader);
      setPayload(decodedPayload);
    } catch (e: any) {
      setHeader(null);
      setPayload(null);
      if (e.message.includes('Invalid Compact JWS')) {
         setError('Invalid JWT structure. The token must have three parts separated by dots.');
      } else if (e.message.includes('base64')) {
        setError('Invalid JWT: Header or Payload is not correctly Base64Url encoded.');
      } else {
        setError('Failed to decode JWT. Please ensure it is a valid token.');
      }
    }
  }

  useEffect(() => {
    if (!encodedToken.trim()) {
      setHeader(null);
      setPayload(null);
      setError(null);
      setVerificationStatus('idle');
      setVerificationError(null);
      return;
    }
    
    decodeToken(encodedToken);
    
    // Asynchronously verify the token when token or key changes
    const verify = async () => {
      if (!secretKey.trim()) {
        setVerificationStatus('idle');
        return;
      }

      try {
        setVerificationError(null);
        const alg = (decodeJwt(encodedToken) as any).alg as string;

        let key: CryptoKey | Uint8Array;
        if (alg.startsWith('HS')) { // Symmetric HMAC algorithms
          key = new TextEncoder().encode(secretKey);
        } else { // Asymmetric algorithms (RS, ES, PS)
            const pemHeader = "-----BEGIN PUBLIC KEY-----";
            const pemFooter = "-----END PUBLIC KEY-----";
            const pemContents = secretKey.substring(pemHeader.length, secretKey.length - pemFooter.length -1).replace(/\s/g, '');
            const binaryDer = new Uint8Array(atob(pemContents).split('').map(c => c.charCodeAt(0)));
            key = await crypto.subtle.importKey(
                'spki',
                binaryDer,
                {
                    name: alg.startsWith('RS') ? 'RSASSA-PKCS1-v1_5' : 'ECDSA',
                    hash: `SHA-${alg.substring(2)}`
                },
                true,
                ['verify']
            );
        }
        
        await jwtVerify(encodedToken, key);
        setVerificationStatus('valid');
      } catch (e: any) {
        setVerificationStatus('invalid');
        if (e.code === 'ERR_JWS_SIGNATURE_VERIFICATION_FAILED') {
            setVerificationError('Signature verification failed.');
        } else if (e.code === 'ERR_JWT_EXPIRED') {
            setVerificationError(`Token expired at ${new Date(payload?.exp * 1000).toLocaleString()}`);
        } else if (e.code === 'ERR_JWT_CLAIM_VALIDATION_FAILED' && e.claim === 'nbf') {
            setVerificationError(`Token is not yet active (nbf: ${new Date(payload?.nbf * 1000).toLocaleString()}).`);
        } else {
            setVerificationError(`Verification Error: ${e.message}. Ensure your key matches the token's algorithm.`);
        }
      }
    };
    
    verify();
    
  }, [encodedToken, secretKey]);


  return (
    <div className="space-y-6">
      <div className="space-y-2">
        <Label htmlFor="encoded-token" className="text-lg font-semibold">Encoded Token</Label>
        <Textarea
          id="encoded-token"
          placeholder="Paste your JWT here..."
          value={encodedToken}
          onChange={(e) => setEncodedToken(e.target.value)}
          className="min-h-[120px] font-mono text-sm"
          aria-label="Encoded JWT"
        />
        {error && (
            <Alert variant="destructive" className="mt-2">
                <XCircle className="h-4 w-4" />
                <AlertTitle>Decoding Error</AlertTitle>
                <AlertDescription>{error}</AlertDescription>
            </Alert>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-2">
          <h3 className="text-lg font-semibold text-primary">Header</h3>
          <pre className="p-4 bg-muted rounded-md text-sm overflow-x-auto font-mono whitespace-pre-wrap">
            {header ? formatJson(header) : '...'}
          </pre>
        </div>
        <div className="space-y-2">
          <h3 className="text-lg font-semibold text-primary">Payload</h3>
          <pre className="p-4 bg-muted rounded-md text-sm overflow-x-auto font-mono whitespace-pre-wrap">
            {payload ? formatJson(payload) : '...'}
          </pre>
        </div>
      </div>
      
       <div className="space-y-2 pt-4 border-t">
          <h3 className="text-lg font-semibold flex items-center gap-2"><Shield className="text-primary"/>Verify Signature</h3>
            <Textarea
              id="secret-key"
              placeholder="Paste your HMAC secret or PEM-formatted public key here"
              value={secretKey}
              onChange={(e) => setSecretKey(e.target.value)}
              className="min-h-[100px] font-mono text-sm"
              aria-label="Secret or Public Key"
              disabled={!encodedToken}
            />
       </div>

      {verificationStatus === 'valid' && (
        <Alert className="border-green-500/50 text-green-700 dark:text-green-400">
            <CheckCircle2 className="h-4 w-4 text-green-500" />
            <AlertTitle>Signature Verified</AlertTitle>
            <AlertDescription>The token&apos;s signature is valid.</AlertDescription>
        </Alert>
      )}
      {verificationStatus === 'invalid' && (
         <Alert variant="destructive">
            <XCircle className="h-4 w-4" />
            <AlertTitle>Invalid Signature</AlertTitle>
            <AlertDescription>{verificationError || 'The token\'s signature is not valid.'}</AlertDescription>
        </Alert>
      )}
       {verificationStatus === 'idle' && encodedToken && (
         <Alert variant="default">
            <Info className="h-4 w-4" />
            <AlertTitle>Verify Signature</AlertTitle>
            <AlertDescription>Paste your secret or public key above to verify the token&apos;s signature.</AlertDescription>
        </Alert>
      )}

       <p className="text-xs text-muted-foreground text-center pt-4">
        All processing is done securely on your local machine. Your token is never sent to our servers.
      </p>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import Papa from 'papaparse';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Loader2, PlusCircle, Sparkles, Trash2, UploadCloud, Merge, Split, Copy, TrendingUp, Info, ShieldQuestion } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { handleKeywordClusterGeneration } from '@/app/actions';
import { Badge } from '@/components/ui/badge';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import { Progress } from '@/components/ui/progress';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import type { Cluster } from '@/ai/flows/generate-keyword-clusters';

const formSchema = z.object({
  primaryKeyword: z.string().min(1, 'Primary keyword is required.'),
  secondaryKeywords: z.array(z.object({
    value: z.string().min(1, "Keyword cannot be empty."),
  })).min(5, 'At least 5 secondary keywords are required.'),
});

type FormValues = z.infer<typeof formSchema>;

interface ClusterResult {
    clusters: Cluster[];
    aiPillarPageSuggestion: string;
    duplicateKeywords: string[];
}

const intentColors: Record<string, string> = {
    Informational: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200 border-blue-200 dark:border-blue-700',
    Transactional: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200 border-green-200 dark:border-green-700',
    Commercial: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200 border-yellow-200 dark:border-yellow-700',
    Navigational: 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200 border-purple-200 dark:border-purple-700',
    Unknown: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200 border-gray-200 dark:border-gray-600',
}

const formatNumber = (num: number) => {
    if (num >= 1000000) return `${(num / 1000000).toFixed(1)}M`;
    if (num >= 1000) return `${(num / 1000).toFixed(1)}K`;
    return num.toString();
};

export function KeywordClusterGenerator() {
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<ClusterResult | null>(null);
  const [fileName, setFileName] = useState<string | null>(null);
  const { toast } = useToast();

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      primaryKeyword: '',
      secondaryKeywords: Array.from({ length: 5 }, () => ({ value: '' })),
    },
    mode: 'onChange',
  });

  const { fields, append, remove, replace } = useFieldArray({
    control: form.control,
    name: 'secondaryKeywords',
  });

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      setFileName(file.name);
      Papa.parse(file, {
        complete: (results) => {
          const keywords = (results.data as string[][]).flat().map(k => k.trim()).filter(Boolean);
          const uniqueKeywords = [...new Set(keywords)];
          replace(uniqueKeywords.map(k => ({ value: k })));
          toast({ title: "Keywords Imported", description: `${uniqueKeywords.length} unique keywords were loaded from the file.`});
        },
        error: (error) => {
            toast({ title: "Import Error", description: `Failed to parse file: ${error.message}`, variant: 'destructive'});
        }
      });
    }
  };

  const handlePaste = (event: React.ClipboardEvent<HTMLTextAreaElement>) => {
    event.preventDefault();
    const pasteData = event.clipboardData.getData('text');
    const keywords = pasteData.split(/\r?\n/).map(k => k.trim()).filter(Boolean);
    if (keywords.length > 0) {
      const uniqueKeywords = [...new Set(keywords)];
      replace(uniqueKeywords.map(k => ({ value: k })));
      toast({ title: "Keywords Pasted", description: `${uniqueKeywords.length} unique keywords were pasted and added.`});
      // Clear the textarea after processing
      const target = event.target as HTMLTextAreaElement;
      target.value = '';
    }
  };
  
  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: "Copied to clipboard!" });
  };

  const onSubmit = async (data: FormValues) => {
    setIsLoading(true);
    setResult(null);

    const formData = new FormData();
    formData.append('primaryKeyword', data.primaryKeyword);
    data.secondaryKeywords.forEach(kw => {
        if (kw.value) formData.append('secondaryKeywords', kw.value);
    });

    try {
      const response = await handleKeywordClusterGeneration(formData);
      if (response.error) {
        throw new Error(response.error);
      }
      setResult(response.data as ClusterResult);
      toast({
        title: 'Clusters Generated!',
        description: 'Your advanced keyword clusters are ready below.',
      });
    } catch (error: any) {
      toast({
        title: 'Generation Failed',
        description: error.message || 'An unexpected error occurred.',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
             <Card>
                <CardHeader>
                    <CardTitle>1. Import Keywords</CardTitle>
                    <CardDescription>Upload a file or paste your keywords. Duplicates will be removed.</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                     <div>
                        <label htmlFor="file-upload" className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed rounded-lg cursor-pointer bg-muted hover:bg-background transition-colors">
                            <div className="flex flex-col items-center justify-center text-center">
                                <UploadCloud className="w-8 h-8 mb-2 text-muted-foreground" />
                                {fileName ? (
                                    <p className="font-semibold text-primary text-sm break-all px-2">{fileName}</p>
                                ) : (
                                <>
                                    <p className="text-sm text-muted-foreground"><span className="font-semibold">Click to upload</span> or drag & drop</p>
                                    <p className="text-xs text-muted-foreground">CSV, TXT, or Excel</p>
                                </>
                                )}
                            </div>
                            <Input id="file-upload" type="file" className="hidden" accept=".csv,.txt,.xlsx,.xls" onChange={handleFileChange} />
                        </label>
                    </div>
                     <div>
                      <Textarea
                        placeholder="Or paste your keywords here, one per line..."
                        onPaste={handlePaste}
                        rows={6}
                        />
                    </div>
                </CardContent>
            </Card>
            <Card>
                <CardHeader>
                    <CardTitle>2. Enter Keywords Manually</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                    <FormField
                    control={form.control}
                    name="primaryKeyword"
                    render={({ field }) => (
                        <FormItem>
                        <FormLabel>Primary / Parent Keyword</FormLabel>
                        <FormControl>
                            <Input placeholder="e.g., 'content marketing'" {...field} />
                        </FormControl>
                        <FormMessage />
                        </FormItem>
                    )}
                    />
                    
                    <div className="space-y-2 max-h-60 overflow-y-auto pr-2">
                    <FormLabel>Secondary Keywords ({[...new Set(form.watch('secondaryKeywords').map(f => f.value).filter(Boolean))].length})</FormLabel>
                    {fields.map((field, index) => (
                        <div key={field.id} className="flex items-center gap-2">
                        <FormField
                            control={form.control}
                            name={`secondaryKeywords.${index}.value`}
                            render={({ field }) => (
                            <FormItem className="flex-grow">
                                <FormControl>
                                <Input placeholder="Enter a secondary keyword..." {...field} />
                                </FormControl>
                                <FormMessage />
                            </FormItem>
                            )}
                        />
                        <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            onClick={() => remove(index)}
                        >
                            <Trash2 className="h-4 w-4 text-muted-foreground" />
                        </Button>
                        </div>
                    ))}
                    </div>

                    <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => append({ value: '' })}
                    >
                    <PlusCircle className="mr-2 h-4 w-4" />
                    Add Keyword
                    </Button>
                </CardContent>
            </Card>
            
            <Button type="submit" className="w-full h-12 text-lg" disabled={isLoading || !form.formState.isValid}>
                {isLoading ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Sparkles className="mr-2 h-5 w-5" />}
                Generate Clusters
            </Button>
          </form>
        </Form>
      </div>
      <div className="lg:col-span-3 space-y-4">
        <Card>
            <CardHeader>
                <CardTitle>Generated Keyword Clusters</CardTitle>
                <CardDescription>
                    AI-powered semantic groups with intent, difficulty, and content strategy suggestions.
                </CardDescription>
            </CardHeader>
            <CardContent>
                {isLoading && (
                    <div className="flex flex-col items-center justify-center text-center p-8 h-96">
                        <Loader2 className="h-12 w-12 text-primary animate-spin mb-4" />
                        <h3 className="text-xl font-semibold">Generating Clusters...</h3>
                        <p className="text-muted-foreground max-w-sm">
                            Analyzing SERP intent and semantic relationships. This can take a moment.
                        </p>
                    </div>
                )}
                {!isLoading && !result && (
                    <div className="text-center py-12 text-muted-foreground border-2 border-dashed rounded-lg h-96 flex items-center justify-center">
                        <p>Your keyword clusters will appear here.</p>
                    </div>
                )}
                {!isLoading && result && (
                    <div className="space-y-6">
                        {result.duplicateKeywords.length > 0 && (
                            <Alert>
                                <Info className="h-4 w-4" />
                                <AlertTitle>Duplicate Keywords Removed</AlertTitle>
                                <AlertDescription>
                                    {result.duplicateKeywords.length} duplicate keywords were found and removed: {result.duplicateKeywords.slice(0, 5).join(', ')}{result.duplicateKeywords.length > 5 ? '...' : ''}
                                </AlertDescription>
                            </Alert>
                        )}
                        <Alert className="bg-primary/5 border-primary/20">
                            <Sparkles className="h-4 w-4 text-primary" />
                            <AlertTitle className="text-primary font-bold">AI Pillar Page Strategy</AlertTitle>
                            <AlertDescription>
                                {result.aiPillarPageSuggestion}
                            </AlertDescription>
                        </Alert>
                        <Accordion type="multiple" className="w-full" defaultValue={result.clusters.map(c => c.clusterTitle)}>
                            {result.clusters.map((cluster, index) => (
                                <AccordionItem value={cluster.clusterTitle} key={index}>
                                    <AccordionTrigger className="text-base font-semibold hover:no-underline">
                                        <div className="flex flex-col md:flex-row md:items-center gap-2 text-left">
                                            <span>{cluster.clusterTitle}</span>
                                            <div className="flex gap-2 items-center">
                                                <Badge variant="outline" className={intentColors[cluster.intent]}>{cluster.intent}</Badge>
                                                <Badge variant="secondary">Parent: {cluster.parentTopic}</Badge>
                                            </div>
                                        </div>
                                    </AccordionTrigger>
                                    <AccordionContent className="space-y-6 pt-4">
                                        
                                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-center">
                                            <Card className='p-2'><CardTitle className='text-lg'>{formatNumber(cluster.searchVolume)}</CardTitle><CardDescription className='text-xs'>Volume</CardDescription></Card>
                                            <Card className='p-2'><CardTitle className='text-lg'>{cluster.difficultyScore}/100</CardTitle><CardDescription className='text-xs'>Difficulty</CardDescription></Card>
                                            <Card className='p-2'><CardTitle className='text-lg'>${cluster.cpc.toFixed(2)}</CardTitle><CardDescription className='text-xs'>CPC</CardDescription></Card>
                                            <Card className='p-2'><CardTitle className='text-lg text-primary'>{cluster.opportunityScore}/100</CardTitle><CardDescription className='text-xs'>Opportunity</CardDescription></Card>
                                        </div>

                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm">
                                             <TooltipProvider>
                                                <Tooltip>
                                                    <TooltipTrigger asChild>
                                                        <div>
                                                            <p className="font-semibold flex items-center gap-1"><TrendingUp className="h-4 w-4 text-muted-foreground"/>Traffic Potential: <span className="font-bold ml-1">{formatNumber(cluster.trafficPotential)}/mo</span></p>
                                                            <Progress value={cluster.trafficPotential / 1000} className="w-full mt-1" />
                                                        </div>
                                                    </TooltipTrigger>
                                                    <TooltipContent><p>Estimated monthly traffic for a top 3 ranking.</p></TooltipContent>
                                                </Tooltip>
                                                 <Tooltip>
                                                    <TooltipTrigger asChild>
                                                        <div>
                                                            <p className="font-semibold flex items-center gap-1"><ShieldQuestion className="h-4 w-4 text-muted-foreground"/>Competition: <span className="font-bold ml-1">{(cluster.competition * 100).toFixed(0)}%</span></p>
                                                            <Progress value={cluster.competition * 100} className="w-full mt-1" />
                                                        </div>
                                                    </TooltipTrigger>
                                                    <TooltipContent><p>Paid search (PPC) competition level.</p></TooltipContent>
                                                </Tooltip>
                                            </TooltipProvider>
                                        </div>
                                        
                                        <div className="flex flex-wrap gap-2 text-sm">
                                            <Badge variant="secondary" className="capitalize">Priority: {cluster.priority}</Badge>
                                            <Badge variant="secondary">Seasonality: {cluster.seasonality}</Badge>
                                        </div>
                                        
                                        <div className="p-3 bg-muted/50 rounded-md">
                                             <h4 className="font-semibold text-sm mb-2">Original Keywords in Cluster ({cluster.keywords.length})</h4>
                                             <div className="flex flex-wrap gap-2">
                                                {cluster.keywords.map((keyword, kwIndex) => (
                                                    <Badge key={kwIndex} variant="outline" className="bg-background">{keyword}</Badge>
                                                ))}
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <h4 className="font-semibold text-sm">AI-Suggested SEO Title</h4>
                                                <div className="flex items-start gap-2">
                                                    <p className="text-sm p-2 bg-muted/50 rounded-md text-muted-foreground flex-grow">&quot;{cluster.aiSeoTitle}&quot;</p>
                                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(cluster.aiSeoTitle)}><Copy/></Button>
                                                </div>
                                            </div>
                                            <div className="space-y-2">
                                                <h4 className="font-semibold text-sm">AI-Suggested Meta Description</h4>
                                                <div className="flex items-start gap-2">
                                                    <p className="text-sm p-2 bg-muted/50 rounded-md text-muted-foreground flex-grow">&quot;{cluster.aiMetaDescription}&quot;</p>
                                                    <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => copyToClipboard(cluster.aiMetaDescription)}><Copy/></Button>
                                                </div>
                                            </div>
                                        </div>
                                        
                                         <div className="space-y-2">
                                            <h4 className="font-semibold text-sm">AI Content Brief</h4>
                                            <div className="prose prose-sm dark:prose-invert max-w-none text-muted-foreground whitespace-pre-wrap p-3 bg-muted/50 rounded-md" dangerouslySetInnerHTML={{ __html: cluster.aiContentBrief.replace(/\*/g, '•') }}></div>
                                        </div>

                                        <div className='p-4 border rounded-lg space-y-4'>
                                            <h4 className="font-semibold text-sm">AI Keyword & Content Expansion</h4>
                                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                <div className="space-y-2">
                                                    <h5 className="font-medium text-xs text-muted-foreground">Related/LSI Keywords</h5>
                                                    <div className="flex flex-wrap gap-2 p-2 bg-muted/50 rounded-md">
                                                        {cluster.aiKeywordExpansion.related.map((kw, i) => <Badge key={i} variant="outline">{kw}</Badge>)}
                                                    </div>
                                                </div>
                                                <div className="space-y-2">
                                                    <h5 className="font-medium text-xs text-muted-foreground">Common Questions</h5>
                                                    <ul className="list-disc pl-5 text-sm text-muted-foreground space-y-1">
                                                        {cluster.aiKeywordExpansion.questions.map((q, i) => <li key={i}>{q}</li>)}
                                                    </ul>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="flex gap-2 pt-4 border-t">
                                            <Button variant="outline" size="sm" disabled><Merge className="mr-2"/>Merge Cluster</Button>
                                            <Button variant="outline" size="sm" disabled><Split className="mr-2"/>Split Cluster</Button>
                                        </div>
                                    </AccordionContent>
                                </AccordionItem>
                            ))}
                         </Accordion>
                    </div>
                )}
            </CardContent>
        </Card>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneLight } from 'react-syntax-highlighter/dist/esm/styles/prism';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Loader2, Sparkles, Copy, Trash2, Wand2, UploadCloud, FileCode, RefreshCw, Milestone } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { handleRegexGeneration, handleRegexDescription } from '@/app/actions';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';

interface RegexResult {
  regex: string;
  explanation: string;
  sampleMatches: string[];
  sampleNonMatches: string[];
}

const formSchema = z.object({
  sampleText: z.string().min(5, 'Please provide at least 5 characters of sample text.'),
  isCaseSensitive: z.boolean(),
  isGlobal: z.boolean(),
  isMultiline: z.boolean(),
  targetLanguage: z.string().min(1, "Please select a language flavor."),
});

type FormValues = z.infer<typeof formSchema>;

const codeSnippets: Record<string, (regex: string) => string> = {
    javascript: (regex) => `const regex = ${regex};\nconst str = \`Your test string\`;\nconst matches = str.match(regex);\nconsole.log(matches);`,
    python: (regex) => {
        const pattern = regex.slice(1, regex.lastIndexOf('/'));
        const flags = regex.slice(regex.lastIndexOf('/') + 1);
        let pyFlags = '';
        if (flags.includes('i')) pyFlags += 're.IGNORECASE | ';
        if (flags.includes('m')) pyFlags += 're.MULTILINE | ';
        if (pyFlags.endsWith(' | ')) pyFlags = pyFlags.slice(0, -3);

        return `import re\n\nregex = r"${pattern}"\ntext = "Your test string"\n\nmatches = re.findall(regex, text${pyFlags ? ', ' + pyFlags : ''})\nprint(matches)`;
    },
    php: (regex) => `$regex = '${regex}';\n$str = 'Your test string';\npreg_match_all($regex, $str, $matches, PREG_SET_ORDER, 0);\n\nvar_dump($matches);`,
    java: (regex) => {
        const pattern = regex.slice(1, regex.lastIndexOf('/'));
        return `import java.util.regex.Pattern;\nimport java.util.regex.Matcher;\n\npublic class RegexExample {\n    public static void main(String[] args) {\n        String text = "Your test string";\n        String pattern = "${pattern}";\n\n        Pattern r = Pattern.compile(pattern);\n        Matcher m = r.matcher(text);\n\n        while (m.find()) {\n            System.out.println("Found match: " + m.group(0));\n        }\n    }\n}`;
    },
    csharp: (regex) => {
        const pattern = regex.slice(1, regex.lastIndexOf('/'));
        return `using System;\nusing System.Text.RegularExpressions;\n\npublic class Example\n{\n    public static void Main()\n    {\n        string text = "Your test string";\n        string pattern = @"${pattern}";\n        foreach (Match match in Regex.Matches(text, pattern))\n        {\n            Console.WriteLine("Found '{0}' at position {1}", match.Value, match.Index);\n        }\n    }\n}`;
    },
    go: (regex) => {
        const pattern = regex.slice(1, regex.lastIndexOf('/'));
        return `package main\n\nimport (\n\t"fmt"\n\t"regexp"\n)\n\nfunc main() {\n\tvar re = regexp.MustCompile(\`${pattern}\`)\n\tvar str = "Your test string"\n\n\tfor _, match := range re.FindAllString(str, -1) {\n\t\tfmt.Println(match)\n\t}\n}`;
    },
    rust: (regex) => {
        const pattern = regex.slice(1, regex.lastIndexOf('/'));
        return `use regex::Regex;\n\nfn main() {\n    let re = Regex::new(r"${pattern}").unwrap();\n    let text = "Your test string";\n\n    for mat in re.find_iter(text) {\n        println!("Found match: {}", mat.as_str());\n    }\n}`;
    }
};


export function RegexGeneratorFromText() {
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<RegexResult | null>(null);
  const [testString, setTestString] = useState('');
  const [replaceString, setReplaceString] = useState('');
  const [selectedLanguage, setSelectedLanguage] = useState('javascript');
  const [activeMode, setActiveMode] = useState('generate');
  const [reverseRegexInput, setReverseRegexInput] = useState('');
  const [reverseRegexResult, setReverseRegexResult] = useState('');
  const { toast } = useToast();

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      sampleText: '',
      isCaseSensitive: false,
      isGlobal: true,
      isMultiline: false,
      targetLanguage: 'javascript',
    },
    mode: 'onChange',
  });

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: 'Copied to clipboard!' });
  };
  
  const clearAll = () => {
    form.reset();
    setResult(null);
    setTestString('');
    setReplaceString('');
    setReverseRegexInput('');
    setReverseRegexResult('');
  }

  const onSubmit = async (data: FormValues) => {
    setIsLoading(true);
    setResult(null);

    try {
      const response = await handleRegexGeneration(data);
      if (response.error) {
        throw new Error(response.error);
      }
      setResult(response.data as RegexResult);
      setTestString(data.sampleText);
      toast({
        title: 'Regex Generated!',
        description: 'Your AI-powered regular expression is ready.',
      });
    } catch (error: any) {
      toast({
        title: 'Generation Failed',
        description: error.message || 'An unexpected error occurred.',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

   const handleDescribeRegex = async () => {
    if (!reverseRegexInput) return;
    setIsLoading(true);
    setReverseRegexResult('');
    try {
        const response = await handleRegexDescription({regex: reverseRegexInput});
        if (response.error) throw new Error(response.error);
        setReverseRegexResult(response.data?.explanation || '');
    } catch (error: any) {
         toast({
            title: 'Description Failed',
            description: error.message || 'Could not describe the regex.',
            variant: 'destructive',
        });
    } finally {
        setIsLoading(false);
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
            const text = e.target?.result as string;
            form.setValue('sampleText', text);
        };
        reader.readAsText(file);
    }
  };
  
  const getHighlightedText = (mode: 'match' | 'replace' = 'match') => {
    if (!result || !testString) {
      return <p className="text-muted-foreground">{mode === 'match' ? 'Enter a test string to see matches.' : 'Enter a test string to see the replacement.'}</p>;
    }
    try {
      const flags = `${form.getValues('isGlobal') ? 'g' : ''}${form.getValues('isCaseSensitive') ? '' : 'i'}${form.getValues('isMultiline') ? 'm' : ''}`;
      const pattern = new RegExp(result.regex.slice(1, result.regex.lastIndexOf('/')), flags);
      
      if (mode === 'replace') {
        const replacedText = testString.replace(pattern, replaceString);
        return <p className="whitespace-pre-wrap">{replacedText}</p>;
      }

      const parts = testString.split(pattern);
      const matches = testString.match(pattern);

      if (!matches) {
        return <span>{testString}</span>;
      }

      return (
        <p className="whitespace-pre-wrap">
          {parts.map((part, i) => (
            <span key={i}>
              {part}
              {i < matches.length && (
                <mark className="bg-primary/20 text-primary font-medium rounded-sm px-1">
                  {matches[i]}
                </mark>
              )}
            </span>
          ))}
        </p>
      );
    } catch (e) {
      return <p className="text-destructive">Invalid regular expression.</p>;
    }
  };


  return (
    <Tabs defaultValue="generate" onValueChange={setActiveMode}>
        <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="generate"><Sparkles className="mr-2"/>Text to Regex (AI)</TabsTrigger>
            <TabsTrigger value="describe"><RefreshCw className="mr-2"/>Regex to English (AI)</TabsTrigger>
        </TabsList>
        <TabsContent value="generate">
            <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 mt-6">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="space-y-6">
                    <Card>
                    <CardHeader>
                        <CardTitle className="flex justify-between items-center">
                            <span>Input</span>
                            <Button type="button" variant="ghost" size="sm" onClick={clearAll}><Trash2 className="mr-2 h-4 w-4"/>Clear All</Button>
                        </CardTitle>
                        <CardDescription>
                        Provide sample text and the AI will generate a regex to match the pattern.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <Tabs defaultValue="paste">
                            <TabsList className="grid w-full grid-cols-2">
                                <TabsTrigger value="paste">Paste Text</TabsTrigger>
                                <TabsTrigger value="upload">Upload File</TabsTrigger>
                            </TabsList>
                            <TabsContent value="paste" className="mt-4">
                                <FormField
                                    control={form.control}
                                    name="sampleText"
                                    render={({ field }) => (
                                        <FormItem>
                                        <FormLabel>Sample Text</FormLabel>
                                        <FormControl>
                                            <Textarea
                                            placeholder={`Paste your text here...\ne.g., "My email is test@example.com"`}
                                            rows={8}
                                            className="font-mono text-sm"
                                            {...field}
                                            />
                                        </FormControl>
                                        <FormMessage />
                                        </FormItem>
                                    )}
                                />
                            </TabsContent>
                            <TabsContent value="upload" className="mt-4">
                                <label htmlFor="file-upload" className="flex flex-col items-center justify-center w-full h-48 border-2 border-dashed rounded-lg cursor-pointer bg-muted hover:bg-background transition-colors">
                                    <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                                        <UploadCloud className="w-10 h-10 mb-3 text-muted-foreground" />
                                        <p className="mb-2 text-sm text-muted-foreground"><span className="font-semibold">Click to upload</span> or drag and drop</p>
                                        <p className="text-xs text-muted-foreground">.TXT file</p>
                                    </div>
                                    <Input id="file-upload" type="file" className="hidden" accept=".txt" onChange={handleFileChange} />
                                </label>
                            </TabsContent>
                        </Tabs>
                    </CardContent>
                    </Card>

                    <Card>
                        <CardHeader>
                            <CardTitle>Pattern Options</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                             <FormField
                                control={form.control}
                                name="targetLanguage"
                                render={({ field }) => (
                                    <FormItem>
                                    <FormLabel>Regex Language/Flavor</FormLabel>
                                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                                        <FormControl>
                                        <SelectTrigger>
                                            <SelectValue placeholder="Select a language flavor" />
                                        </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            <SelectItem value="javascript">JavaScript</SelectItem>
                                            <SelectItem value="python">Python</SelectItem>
                                            <SelectItem value="pcre">PCRE (PHP)</SelectItem>
                                            <SelectItem value="java">Java</SelectItem>
                                            <SelectItem value="go">Go (RE2)</SelectItem>
                                            <SelectItem value="rust">Rust</SelectItem>
                                            <SelectItem value="dotnet">.NET (C#)</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                    </FormItem>
                                )}
                                />
                            <div className="flex flex-wrap gap-x-4 gap-y-2">
                                <FormField
                                    control={form.control}
                                    name="isCaseSensitive"
                                    render={({ field }) => (
                                        <FormItem className="flex flex-row items-start space-x-2 space-y-0">
                                        <FormControl><Checkbox checked={field.value} onCheckedChange={field.onChange} /></FormControl>
                                        <FormLabel className="font-normal">Case Sensitive</FormLabel>
                                        </FormItem>
                                    )}
                                />
                                <FormField
                                    control={form.control}
                                    name="isGlobal"
                                    render={({ field }) => (
                                        <FormItem className="flex flex-row items-start space-x-2 space-y-0">
                                        <FormControl><Checkbox checked={field.value} onCheckedChange={field.onChange} /></FormControl>
                                        <FormLabel className="font-normal">Global Match</FormLabel>
                                        </FormItem>
                                    )}
                                />
                                <FormField
                                    control={form.control}
                                    name="isMultiline"
                                    render={({ field }) => (
                                        <FormItem className="flex flex-row items-start space-x-2 space-y-0">
                                        <FormControl><Checkbox checked={field.value} onCheckedChange={field.onChange} /></FormControl>
                                        <FormLabel className="font-normal">Multi-line</FormLabel>
                                        </FormItem>
                                    )}
                                />
                            </div>
                        </CardContent>
                    </Card>

                    <Button
                    type="submit"
                    className="w-full h-12 text-lg"
                    disabled={isLoading || !form.formState.isValid}
                    >
                    {isLoading ? (
                        <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                    ) : (
                        <Sparkles className="mr-2 h-5 w-5" />
                    )}
                    Generate Regex
                    </Button>
                </div>
                <div className="space-y-6">
                    <Card>
                    <CardHeader>
                        <CardTitle>Output</CardTitle>
                        <CardDescription>
                        The generated regular expression and an explanation of how it works.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        {isLoading ? (
                        <div className="flex flex-col items-center justify-center text-center p-8 h-64">
                            <Loader2 className="h-12 w-12 text-primary animate-spin mb-4" />
                            <h3 className="text-xl font-semibold">Generating Regex...</h3>
                            <p className="text-muted-foreground">The AI is analyzing your text.</p>
                        </div>
                        ) : result ? (
                        <Tabs defaultValue="explanation" className="w-full">
                            <TabsList className="grid w-full grid-cols-3">
                                <TabsTrigger value="explanation"><Wand2 className="mr-2"/>AI Explanation</TabsTrigger>
                                <TabsTrigger value="snippets"><FileCode className="mr-2"/>Code Snippets</TabsTrigger>
                                <TabsTrigger value="samples"><Milestone className="mr-2"/>Samples</TabsTrigger>
                            </TabsList>
                            <TabsContent value="explanation" className="mt-4 space-y-4">
                                <div>
                                <FormLabel>Generated Regex</FormLabel>
                                <div className="relative mt-1">
                                    <div className="bg-muted rounded-md p-3 font-mono text-sm overflow-x-auto">
                                        {result.regex}
                                    </div>
                                    <Button variant="ghost" size="icon" className="absolute top-1 right-1 h-8 w-8" onClick={() => copyToClipboard(result.regex)}><Copy/></Button>
                                </div>
                                </div>
                                <div>
                                <FormLabel>Explanation</FormLabel>
                                <div className="text-sm p-3 bg-muted rounded-md text-muted-foreground prose prose-sm dark:prose-invert max-w-none mt-1" dangerouslySetInnerHTML={{ __html: result.explanation.replace(/\n/g, '<br/>') }}></div>
                                </div>
                            </TabsContent>
                            <TabsContent value="snippets" className="mt-4 space-y-4">
                                <Select value={selectedLanguage} onValueChange={setSelectedLanguage}>
                                    <SelectTrigger>
                                        <SelectValue placeholder="Select language" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="javascript">JavaScript</SelectItem>
                                        <SelectItem value="python">Python</SelectItem>
                                        <SelectItem value="php">PHP (PCRE)</SelectItem>
                                        <SelectItem value="java">Java</SelectItem>
                                        <SelectItem value="csharp">C# (.NET)</SelectItem>
                                        <SelectItem value="go">Go (RE2)</SelectItem>
                                        <SelectItem value="rust">Rust</SelectItem>
                                    </SelectContent>
                                </Select>
                                <div className="relative">
                                    <SyntaxHighlighter language={selectedLanguage} style={oneLight} className="!mt-1 !p-3 !rounded-md !bg-muted" showLineNumbers>
                                        {codeSnippets[selectedLanguage](result.regex)}
                                    </SyntaxHighlighter>
                                    <Button variant="ghost" size="icon" className="absolute top-2 right-2 h-8 w-8" onClick={() => copyToClipboard(codeSnippets[selectedLanguage](result.regex))}><Copy/></Button>
                                </div>
                            </TabsContent>
                             <TabsContent value="samples" className="mt-4 space-y-4">
                                <Alert>
                                    <AlertTitle>AI-Generated Samples</AlertTitle>
                                    <AlertDescription>These are examples of what will and won&apos;t match.</AlertDescription>
                                </Alert>
                                <div>
                                    <FormLabel>Matching Examples</FormLabel>
                                    <div className="text-sm p-3 bg-green-500/10 text-green-800 dark:text-green-300 border border-green-500/20 rounded-md mt-1">
                                        {result.sampleMatches.map((s, i) => <p key={i} className="font-mono">{s}</p>)}
                                    </div>
                                </div>
                                <div>
                                    <FormLabel>Non-Matching Examples</FormLabel>
                                    <div className="text-sm p-3 bg-red-500/10 text-red-800 dark:text-red-300 border border-red-500/20 rounded-md mt-1">
                                        {result.sampleNonMatches.map((s, i) => <p key={i} className="font-mono">{s}</p>)}
                                    </div>
                                </div>
                             </TabsContent>
                        </Tabs>
                        ) : (
                        <div className="text-center py-12 text-muted-foreground border-2 border-dashed rounded-lg h-64 flex items-center justify-center">
                            <p>Your generated regex will appear here.</p>
                        </div>
                        )}
                    </CardContent>
                    </Card>
                    
                    <Card>
                        <CardHeader><CardTitle>Live Tester</CardTitle></CardHeader>
                        <CardContent className="space-y-4">
                             <Tabs defaultValue="match">
                                <TabsList className="grid w-full grid-cols-2">
                                    <TabsTrigger value="match">Match</TabsTrigger>
                                    <TabsTrigger value="replace">Replace</TabsTrigger>
                                </TabsList>
                                <TabsContent value="match" className="mt-4">
                                    <div className="space-y-1">
                                        <FormLabel htmlFor="test-string">Test String</FormLabel>
                                        <Textarea 
                                            id="test-string"
                                            placeholder="Paste text here to test the regex against it."
                                            value={testString}
                                            onChange={(e) => setTestString(e.target.value)}
                                            rows={4}
                                            disabled={!result}
                                        />
                                    </div>
                                    <div className="space-y-1 mt-4">
                                        <FormLabel>Matches</FormLabel>
                                        <div className="p-3 bg-muted rounded-md min-h-[80px] text-sm">
                                            {getHighlightedText('match')}
                                        </div>
                                    </div>
                                </TabsContent>
                                <TabsContent value="replace" className="mt-4">
                                     <div className="space-y-1">
                                        <FormLabel htmlFor="test-string-replace">Test String</FormLabel>
                                        <Textarea 
                                            id="test-string-replace"
                                            placeholder="Paste text here to test the regex against it."
                                            value={testString}
                                            onChange={(e) => setTestString(e.target.value)}
                                            rows={4}
                                            disabled={!result}
                                        />
                                    </div>
                                     <div className="space-y-1 mt-4">
                                        <FormLabel htmlFor="replace-string">Replacement String</FormLabel>
                                        <Input
                                            id="replace-string"
                                            placeholder="Use $1, $2 for capture groups"
                                            value={replaceString}
                                            onChange={(e) => setReplaceString(e.target.value)}
                                            disabled={!result}
                                            className="font-mono"
                                        />
                                    </div>
                                    <div className="space-y-1 mt-4">
                                        <FormLabel>Result</FormLabel>
                                        <div className="p-3 bg-muted rounded-md min-h-[80px] text-sm">
                                            {getHighlightedText('replace')}
                                        </div>
                                    </div>
                                </TabsContent>
                             </Tabs>
                        </CardContent>
                    </Card>

                </div>
                </div>
            </form>
            </Form>
        </TabsContent>
        <TabsContent value="describe">
             <div className="space-y-6 mt-6">
                <Card>
                    <CardHeader>
                        <CardTitle>Describe Regex</CardTitle>
                        <CardDescription>Paste any regular expression below and the AI will explain it in plain English.</CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <Textarea
                            placeholder="/(d{3})-(d{3})-(d{4})/"
                            value={reverseRegexInput}
                            onChange={(e) => setReverseRegexInput(e.target.value)}
                            className="font-mono"
                        />
                        <Button onClick={handleDescribeRegex} disabled={isLoading || !reverseRegexInput}>
                            {isLoading ? <Loader2 className="mr-2 animate-spin"/> : <RefreshCw className="mr-2"/>}
                            Describe Regex
                        </Button>
                    </CardContent>
                </Card>
                 {(isLoading || reverseRegexResult) && (
                    <Card>
                        <CardHeader>
                            <CardTitle>AI Explanation</CardTitle>
                        </CardHeader>
                        <CardContent>
                            {isLoading ? (
                                <div className="flex items-center gap-2 text-muted-foreground">
                                    <Loader2 className="animate-spin"/> Analyzing...
                                </div>
                            ) : (
                                <div className="text-sm p-3 bg-muted rounded-md text-muted-foreground prose prose-sm dark:prose-invert max-w-none" dangerouslySetInnerHTML={{ __html: reverseRegexResult.replace(/\n/g, '<br/>') }}></div>
                            )}
                        </CardContent>
                    </Card>
                 )}
             </div>
        </TabsContent>
    </Tabs>
  );
}

import { tools } from '@/lib/tools';
import { notFound } from 'next/navigation';
import { generateSEOMetadata } from '@/ai/flows/generate-seo-metadata';
import { ToolPageClient } from '@/components/tool-page/tool-page-client';
import type { Metadata } from 'next';
import { placeholderImages } from '@/lib/placeholder-images';

const SLUG = 'tinyurl-maker';

export async function generateMetadata(): Promise<Metadata> {
  const tool = tools.find((t) => t.slug === SLUG);

  if (!tool) {
    return {
      title: 'Tool not found',
    };
  }

  const { seoTitle, seoDescription } = await generateSEOMetadata({
    toolName: tool.name,
    toolDescription: tool.longDescription,
    toolSlug: tool.slug,
  });

  return {
    alternates: {
      canonical: `https://all2ools.com/tools/${SLUG}`,
    },
    title: 'TinyURL Maker – Free URL Shortener Tool',
    description: 'Create clean, fast, trackable short links instantly.',
    openGraph: {
      title: 'TinyURL Maker – Free URL Shortener Tool',
      description: 'Create clean, fast, trackable short links instantly.',
      type: 'website',
      url: `https://all2ools.com/tools/tinyurl-maker`,
    },
  };
}

export default async function ToolPage() {
  const tool = tools.find((t) => t.slug === SLUG);

  if (!tool) {
    notFound();
  }
  
  const faqContent = [
      '1. Is this URL shortener free to use? \nYes, this tool is completely free to use. There are no hidden charges or subscription fees.',
      '2. Do the shortened links expire? \nNo, the links you create with our tool do not expire. They will continue to work indefinitely.',
      '3. Can I customize the shortened URL? \nYes, you can use the "Custom Slug" field to create a personalized, branded short link that is easy to remember.',
      '4. Is my data and privacy secure? \nWe do not store any personal data associated with the links you create. The history of your last 5 links is stored locally on your device\'s browser and is not sent to our servers.',
      '5. What kind of analytics do you provide? \nWe provide basic, privacy-friendly analytics, including the total number of clicks a link has received and the timestamp of the last click. We do not track individual users.',
      '6. Can I use this for commercial purposes? \nAbsolutely. You are free to use the shortened links for your business, marketing campaigns, or any other commercial activity.'
    ].join('\n\n');
    
  const aiContent = await generateSEOMetadata({
    toolName: tool.name,
    toolDescription: tool.longDescription,
    toolSlug: tool.slug,
  });

  aiContent.faqContent = faqContent;

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'WebApplication',
    name: 'TinyURL Maker – Free URL Shortener',
    description: 'Create clean, fast, trackable short links instantly.',
    applicationCategory: 'DeveloperApplication',
    operatingSystem: 'Any',
    url: 'https://all2ools.com/tools/tinyurl-maker',
    offers: {
      '@type': 'Offer',
      price: '0',
    },
  };
  aiContent.jsonLdSchema = JSON.stringify(jsonLd, null, 2);

  const image = placeholderImages.find((img) => img.id === tool.slug);
  const toolWithImage = {
    ...tool,
    image: image?.imageUrl || `https://picsum.photos/seed/${tool.slug}/1200/400`,
    imageHint: image?.imageHint || 'tool banner',
  };
  return (
    <ToolPageClient
      tool={toolWithImage}
      aiContent={aiContent}
    />
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/hooks/use-toast';
import { Copy, Trash2, RefreshCw, Bot, Loader2, Link as LinkIcon, Info } from 'lucide-react';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneDark, oneLight } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { Alert, AlertTitle, AlertDescription } from '@/components/ui/alert';
import { generateWebhookPayload } from '@/ai/flows/webhook-tester';
import { useTheme } from 'next-themes';

interface WebhookRequest {
  id: string;
  method: string;
  headers: Record<string, string>;
  query: Record<string, string>;
  body: any;
  timestamp: string;
}

export function WebhookTester() {
  const [requests, setRequests] = useState<WebhookRequest[]>([]);
  const [selectedRequest, setSelectedRequest] = useState<WebhookRequest | null>(null);
  const [uniqueUrl, setUniqueUrl] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const { toast } = useToast();
  const { resolvedTheme } = useTheme();

  useEffect(() => {
    // In a real application, this would be fetched from a backend service
    // that generates a truly unique endpoint.
    const mockId = `ep_${Math.random().toString(36).substring(2, 10)}`;
    setUniqueUrl(`https://all2ools.com/api/webhooks/${mockId}`);
  }, []);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: 'Copied to clipboard!' });
  };
  
  const handleGenerateMockRequest = async (type: 'github' | 'stripe') => {
    setIsGenerating(true);
    try {
        const result = await generateWebhookPayload({type});
        
        const newRequest: WebhookRequest = {
            id: `req_${Math.random().toString(36).substring(2, 9)}`,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'User-Agent': type === 'github' ? 'GitHub-Hookshot/1.0' : 'Stripe/1.0',
                ...(type === 'github' && {'X-GitHub-Event': 'push'}),
                ...(type === 'stripe' && {'Stripe-Signature': 'whsec_...'})
            },
            query: {},
            body: result.payload,
            timestamp: new Date().toISOString()
        };
        
        setRequests(prev => [newRequest, ...prev]);
        setSelectedRequest(newRequest);
        toast({ title: 'Mock Request Received', description: `A mock ${type} webhook has been generated.` });

    } catch (e: any) {
        toast({ title: "Generation Failed", description: e.message, variant: 'destructive'});
    } finally {
        setIsGenerating(false);
    }
  }

  const memoizedSyntaxHighlighterTheme = useMemo(
    () => (resolvedTheme === 'dark' ? oneDark : oneLight),
    [resolvedTheme]
  );

  return (
    <div className="space-y-4">
       <Alert variant="default" className="border-amber-500/50 text-amber-700 dark:text-amber-400">
        <Info className="h-4 w-4 text-amber-500" />
        <AlertTitle>This is a UI Demonstration</AlertTitle>
        <AlertDescription>
          This tool is a demonstration of the user interface. Incoming requests are simulated. A real backend is required to receive live webhooks.
        </AlertDescription>
      </Alert>

      <Card>
        <CardContent className="p-4 flex flex-col md:flex-row items-center gap-4">
            <div className="flex-grow w-full">
                <label htmlFor="webhook-url" className="text-sm font-medium text-muted-foreground">Your unique webhook URL</label>
                <div className="flex gap-2 mt-1">
                    <Input id="webhook-url" readOnly value={uniqueUrl} className="font-mono bg-muted" />
                    <Button variant="outline" size="icon" onClick={() => copyToClipboard(uniqueUrl)}><Copy className="h-4 w-4"/></Button>
                </div>
            </div>
             <div className="flex items-center gap-2 w-full md:w-auto">
                <Button onClick={() => handleGenerateMockRequest('github')} disabled={isGenerating} className="w-full sm:w-auto">
                    {isGenerating ? <Loader2 className="mr-2 animate-spin"/> : <Bot className="mr-2"/>}
                    Generate GitHub Event
                </Button>
                 <Button onClick={() => handleGenerateMockRequest('stripe')} disabled={isGenerating} className="w-full sm:w-auto">
                     {isGenerating ? <Loader2 className="mr-2 animate-spin"/> : <Bot className="mr-2"/>}
                    Generate Stripe Event
                </Button>
            </div>
        </CardContent>
      </Card>
      
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 h-[70vh]">
        <Card className="md:col-span-1 flex flex-col">
            <CardHeader className="flex flex-row items-center justify-between p-4 border-b">
                <CardTitle className="text-lg">Requests ({requests.length})</CardTitle>
                <div className="flex gap-1">
                    <Button variant="ghost" size="icon" disabled><RefreshCw className="h-4 w-4"/></Button>
                    <Button variant="ghost" size="icon" onClick={() => { setRequests([]); setSelectedRequest(null); }}><Trash2 className="h-4 w-4 text-destructive"/></Button>
                </div>
            </CardHeader>
            <ScrollArea className="flex-grow">
                <div className="p-2">
                    {requests.length === 0 ? (
                        <p className="text-center text-sm text-muted-foreground p-4">Waiting for requests...</p>
                    ) : (
                        requests.map(req => (
                            <button
                                key={req.id}
                                onClick={() => setSelectedRequest(req)}
                                className={`w-full text-left p-2 rounded-md flex items-center gap-2 ${selectedRequest?.id === req.id ? 'bg-primary/10' : 'hover:bg-muted'}`}
                            >
                               <Badge variant={req.method === 'POST' ? 'default' : 'secondary'} className="w-16 justify-center">{req.method}</Badge>
                               <span className="font-mono text-sm truncate">{req.id}</span>
                            </button>
                        ))
                    )}
                </div>
            </ScrollArea>
        </Card>
        
        <div className="md:col-span-3">
            {selectedRequest ? (
                <Card className="h-full flex flex-col">
                     <Tabs defaultValue="body" className="w-full flex-grow flex flex-col">
                        <div className="p-2 border-b">
                             <TabsList>
                                <TabsTrigger value="body">Body</TabsTrigger>
                                <TabsTrigger value="headers">Headers ({Object.keys(selectedRequest.headers).length})</TabsTrigger>
                                <TabsTrigger value="query">Query Params ({Object.keys(selectedRequest.query).length})</TabsTrigger>
                            </TabsList>
