export type ConversionType = 
  | "pdf-to-word" | "word-to-pdf" 
  | "pdf-to-jpg" | "jpg-to-pdf" 
  | "pdf-to-excel" | "excel-to-pdf"
  | "pdf-to-ppt" | "ppt-to-pdf"
  | "html-to-pdf"
  | "merge-pdf" | "split-pdf"
