function FileDropZone({
  conversionType,
  conversionInfo,
  status,
  files,
  additionalParams,
  progress,
  convertedFile,
  handleFileChange,
  handleParamChange,
  handleConvert,
  handleDownload,
  resetState,
  setFiles,
  htmlContent,
  setHtmlContent,
}: {
  conversionType: ConversionType;
  conversionInfo: ReturnType<typeof getConversionInfo>;
  status: ConversionStatus;
  files: File[];
  additionalParams: Record<string, string>;
  progress: number;
  convertedFile: { blob: Blob; name: string } | null;
  handleFileChange: (e: ChangeEvent<HTMLInputElement>) => void;
  handleParamChange: (id: string, value: string) => void;
  handleConvert: () => void;
  handleDownload: () => void;
  resetState: () => void;
  setFiles: (files: File[]) => void;
  htmlContent: string;
  setHtmlContent: (content: string) => void;
}) {
  const { fromIcon, toIcon, fromType, actionText, accept, multiple, params } = conversionInfo;

  const handleLocalFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setHtmlContent(""); // Clear text content if a file is selected
    }
    handleFileChange(e);
  };

  const handleLocalHtmlChange = (e: ChangeEvent<HTMLTextAreaElement>) => {
    const content = e.target.value;
    if (content) {
      setFiles([]); // Clear file if text is entered
    }
    setHtmlContent(content);
  }

  const renderHtmlToPdfInputs = () => (
    <div className="space-y-6">
      <div className="flex justify-center items-center gap-6">
        {fromIcon}
        <ArrowRight className="h-8 w-8 text-muted-foreground" />
        {toIcon}
      </div>

      <FileDropZoneCore 
        fromType={fromType} 
        accept={accept} 
        multiple={false} 
        handleFileChange={handleLocalFileChange} 
        files={files}
        status={status}
        disabled={!!htmlContent}
      />
       {files.length > 0 && (
        <FilePreview files={files} fromIcon={fromIcon} onRemove={resetState} isSingle={true} />
       )}

      <div className="relative my-4">
        <div className="absolute inset-0 flex items-center">
            <span className="w-full border-t" />
        </div>
        <div className="relative flex justify-center text-xs uppercase">
            <span className="bg-background px-2 text-muted-foreground">Or Paste Code</span>
        </div>
      </div>

      <Textarea
        placeholder="Paste your HTML code here"
        className="h-48"
        value={htmlContent}
        onChange={handleLocalHtmlChange}
        disabled={files.length > 0}
      />
    </div>
  );

  const renderDefaultInputs = () => (
     <div className="space-y-6">
      <div className="flex justify-center items-center gap-6">
        {fromIcon}
        <ArrowRight className="h-8 w-8 text-muted-foreground" />
        {toIcon}
      </div>

      {(status === "idle" || status === "file-selected") && (
          <FileDropZoneCore 
            fromType={fromType} 
            accept={accept} 
            multiple={multiple} 
            handleFileChange={handleFileChange}
            files={files}
            status={status}
            disabled={false}
          />
      )}

      {files.length > 0 && (status === "file-selected" || status === "converting" || status === "done" || status === 'error') && (
         <FilePreview files={files} fromIcon={fromIcon} onRemove={(index) => {
            if (multiple) {
                setFiles(files.filter((_, i) => i !== index));
            } else {
                resetState();
            }
         }} isSingle={!multiple} />
      )}
     </div>
  );

  return (
    <div className="space-y-6">
       {conversionType === 'html-to-pdf' ? renderHtmlToPdfInputs() : renderDefaultInputs()}

      {status === "file-selected" && params && params.length > 0 && (
          <div className="grid gap-4">
              {params.map(param => (
                  <div key={param.id} className="grid gap-2">
                      <Label htmlFor={param.id}>{param.label}</Label>
                      {param.type === 'select' ? (
                        <Select onValueChange={(value) => handleParamChange(param.id, value)} defaultValue={additionalParams[param.id]}>
                          <SelectTrigger id={param.id}>
                            <SelectValue placeholder={param.label} />
                          </SelectTrigger>
                          <SelectContent>
                            {param.options?.map(option => <SelectItem key={option} value={option}>{option}</SelectItem>)}
                          </SelectContent>
                        </Select>
                      ) : (
                        <Input 
                          id={param.id} 
                          type={param.type}
                          placeholder={param.label}
                          value={additionalParams[param.id] || ''}
                          onChange={(e) => handleParamChange(param.id, e.target.value)}
                        />
                      )}
                  </div>
              ))}
          </div>
      )}

      {status === 'converting' && (
        <div className="space-y-2 text-center">
          <Progress value={progress} className="w-full" />
          <p className="text-sm text-muted-foreground animate-pulse">Converting... {progress}%</p>
        </div>
      )}

      {(status === "file-selected") && (
        <Button onClick={handleConvert} className="w-full" size="lg" disabled={files.length === 0 && !htmlContent}>
          {actionText}
        </Button>
      )}

      {status === "done" && (
        <div className="grid gap-4 sm:grid-cols-2">
           <Button onClick={handleDownload} className="w-full" size="lg">
            <Download className="mr-2 h-4 w-4" />
            Download File
          </Button>
          <Button onClick={resetState} className="w-full" size="lg" variant="outline">
            Convert Another
          </Button>
        </div>
      )}
    </div>
  );
}

function FileDropZoneCore({ fromType, accept, multiple, handleFileChange, files, status, disabled }: {
  fromType: string;
  accept: string;
  multiple: boolean;
  handleFileChange: (e: ChangeEvent<HTMLInputElement>) => void;
  files: File[];
  status: ConversionStatus;
  disabled: boolean;
}) {
  if (status !== 'idle' && status !== 'file-selected') return null;
  if (files.length > 0 && !multiple) return null;

  const baseClasses = "relative border-2 border-dashed border-border rounded-lg p-10 text-center transition-colors group";
  const enabledClasses = "hover:border-primary";
  const disabledClasses = "bg-secondary/50 cursor-not-allowed opacity-50";

  return (
    <div className={cn(baseClasses, disabled ? disabledClasses : enabledClasses)}>
      <div className="absolute inset-0 bg-accent opacity-0 group-hover:opacity-10 transition-opacity rounded-lg" />
      <UploadCloud className="mx-auto h-12 w-12 text-muted-foreground" />
      <p className="mt-4 font-semibold text-foreground">
        Drop your {fromType} file{multiple ? 's' : ''} here
      </p>
      <p className="text-sm text-muted-foreground">or click to browse</p>
      <Input
        id="file-upload"
        type="file"
        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
        onChange={handleFileChange}
        accept={accept}
        multiple={multiple}
        aria-label={`Upload ${fromType} file`}
        disabled={disabled}
      />
    </div>
  );
}

function FilePreview({ files, fromIcon, onRemove, isSingle }: {
  files: File[];
  fromIcon: React.ReactNode;
  onRemove: (index: number) => void;
  isSingle: boolean;
}) {
  return (
     <div className="border rounded-lg p-4 space-y-2 bg-secondary/50 relative">
        {files.map((file, index) => (
            <div key={index} className="flex items-center justify-between">
                <div className="flex items-center gap-3 overflow-hidden">
                    {fromIcon}
                    <span className="font-medium text-sm truncate">{file.name}</span>
                </div>
                {!isSingle ? (
                 <Button variant="ghost" size="icon" onClick={() => onRemove(index)} aria-label="Remove file">
                  <X className="h-4 w-4" />
                </Button>
               ) : null}
            </div>
        ))}
        {isSingle && files.length > 0 && (
             <Button variant="ghost" size="icon" className="absolute top-2 right-2" onClick={() => onRemove(0)} aria-label="Remove file">
              <X className="h-4 w-4" />
            </Button>
        )}
        {!isSingle && files.length > 1 && (
             <Button variant="ghost" size="sm" onClick={() => files.forEach((_, i) => onRemove(i))} className="w-full">
                Remove All
            </Button>
        )}
      </div>
  )
}

export function FileConverter({ conversionType, setConversionType }: FileConverterProps) {
  const [files, setFiles] = useState<File[]>([]);
  const [htmlContent, setHtmlContent] = useState<string>("");
  const [status, setStatus] = useState<ConversionStatus>("idle");
  const [progress, setProgress] = useState(0);
  const [convertedFile, setConvertedFile] = useState<{ blob: Blob, name: string } | null>(null);
  const [additionalParams, setAdditionalParams] = useState<Record<string, string>>({});
  const { toast } = useToast();

  const conversionInfo = useMemo(() => getConversionInfo(conversionType), [conversionType]);

  const onTabChange = (value: string) => {
    setConversionType(value as ConversionType);
  };

  useEffect(() => {
    resetState();
  }, [conversionType]);

  useEffect(() => {
    if (files.length > 0 || htmlContent) {
        setStatus('file-selected');
    } else {
        setStatus('idle');
    }
  }, [files, htmlContent]);

  const resetState = () => {
    setFiles([]);
    setHtmlContent("");
    setStatus("idle");
    setProgress(0);
    setConvertedFile(null);
    const newParams: Record<string, string> = {};
    getConversionInfo(conversionType).params.forEach(param => {
      if (param.id === 'position') newParams[param.id] = 'bottom-center';
      if (param.id === 'margin') newParams[param.id] = '10';
      if (param.id === 'pages') newParams[param.id] = 'all';
      if (param.id === 'page') newParams[param.id] = '1';
      if (param.id === 'x') newParams[param.id] = '100';
      if (param.id === 'y') newParams[param.id] = '100';
      if (param.id === 'text') newParams[param.id] = 'Your Text Here';
      if (param.id === 'fontsize') newParams[param.id] = '12';
    });
    setAdditionalParams(newParams);
    const fileInput = document.getElementById('file-upload') as HTMLInputElement;
    if (fileInput) {
      fileInput.value = '';
    }
  };


  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const selectedFiles = Array.from(e.target.files);
      setFiles(selectedFiles);
    }
  };

  const handleHtmlContentChange = (content: string) => {
    setHtmlContent(content);
  }

  const handleParamChange = (id: string, value: string) => {
    setAdditionalParams(prev => ({...prev, [id]: value}));
  };

  const handleConvert = async () => {
    if (files.length === 0 && !htmlContent) return;

    setStatus("converting");
    setProgress(0);

    const animateProgress = () => {
      const interval = setInterval(() => {
        setProgress((prev) => {
          if (prev >= 95) {
            clearInterval(interval);
            return 95;
          }
          return prev + 5;
        });
      }, 200);
      return interval;
    };
    const progressInterval = animateProgress();

    try {
      const formData = new FormData();
      formData.append("conversionType", conversionType);

      if (conversionType === 'html-to-pdf') {
        if (files.length > 0) {
          formData.append("file", files[0]);
        } else if (htmlContent) {
          formData.append("html", htmlContent);
        }
      } else {
        files.forEach((file) => {
            formData.append("files", file);
        });
      }

      for (const key in additionalParams) {
        formData.append(key, additionalParams[key]);
      }

      const response = await fetch('/api/convert', {
        method: 'POST',
        body: formData,
      });

      clearInterval(progressInterval);

      if (!response.ok) {
        let errorMessage = `Conversion failed with status ${response.status}`;
        try {
            const errorBody = await response.text();
            if (response.headers.get('Content-Type')?.includes('application/json')) {
                const errorJson = JSON.parse(errorBody);
                 if (errorJson.message) {
                    errorMessage = errorJson.message;
                 } else if (errorJson.detail) {
                    if (typeof errorJson.detail === 'string') {
                        errorMessage = errorJson.detail;
                    } else if (Array.isArray(errorJson.detail) && errorJson.detail[0]?.msg) {
                        errorMessage = errorJson.detail.map((d: any) => `${d.loc.join(' -> ')}: ${d.msg}`).join(', ');
                    } else {
                        errorMessage = JSON.stringify(errorJson.detail);
                    }
                 }
            } else if (errorBody && !errorBody.trim().startsWith('<')) {
                errorMessage = errorBody;
            }
        } catch (e) {
            // Parsing failed, do nothing and keep the default message
        }

        throw new Error(errorMessage);
      }

      setProgress(100);

      const blob = await response.blob();
      const contentDisposition = response.headers.get('content-disposition');
      let filename = "converted-file";
      if (contentDisposition) {
        const filenameMatch = contentDisposition.match(/filename="?(.+)"?/i);
        if (filenameMatch && filenameMatch.length > 1) {
          filename = filenameMatch[1];
        }
      }

      setConvertedFile({ blob, name: filename });
      setStatus("done");
      toast({
        title: "Conversion Successful!",
        description: "Your file is ready for download.",
      });

    } catch (error) {
      clearInterval(progressInterval);
      setStatus("error");
      const errorMessage = error instanceof Error ? error.message : "An unknown error occurred.";
      console.error(error);
      toast({
        title: "Conversion Error",
        description: errorMessage,
        variant: "destructive",
      });
      setTimeout(() => {
         if (files.length > 0 || htmlContent) {
            setStatus("file-selected");
        } else {
            resetState();
        }
      }, 3000);
    }
  };

  const handleDownload = () => {
    if (!convertedFile) return;

    const url = URL.createObjectURL(convertedFile.blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = convertedFile.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    toast({
      title: "Download Started",
      description: `Downloading ${convertedFile.name}.`,
    });
  };

  const isTabbedTool = conversionType === 'pdf-to-word' || conversionType === 'word-to-pdf';

  const MainContent = (
     <div className="pt-6">
       <FileDropZone
        key={conversionType}
        conversionType={conversionType}
        conversionInfo={conversionInfo}
        status={status}
        files={files}
        additionalParams={additionalParams}
        progress={progress}
        convertedFile={convertedFile}
        handleFileChange={handleFileChange}
        handleParamChange={handleParamChange}
        handleConvert={handleConvert}
        handleDownload={handleDownload}
        resetState={resetState}
        setFiles={setFiles}
        htmlContent={htmlContent}
        setHtmlContent={handleHtmlContentChange}
      />
    </div>
  );

  return (
    <Card className="w-full max-w-2xl shadow-xl border-t-4 border-primary">
      <CardHeader className="text-center">
        <CardTitle className="text-3xl font-headline">{conversionInfo.title}</CardTitle>
        <CardDescription>The simplest way to convert your documents.</CardDescription>
      </CardHeader>
      <CardContent>
        {isTabbedTool ? (
          <Tabs value={conversionType} onValueChange={onTabChange} className="w-full">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="pdf-to-word">PDF to Word</TabsTrigger>
              <TabsTrigger value="word-to-pdf">Word to PDF</TabsTrigger>
            </TabsList>
            <TabsContent value="pdf-to-word" className="pt-6">
              {conversionType === 'pdf-to-word' && MainContent}
            </TabsContent>
            <TabsContent value="word-to-pdf" className="pt-6">
              {conversionType === 'word-to-pdf' && MainContent}
            </TabsContent>
          </Tabs>
        ) : (
          MainContent
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { QRConfig } from "./types";
import { Globe, Type, Mail, Phone, MessageSquare, Wifi, User, MapPin } from "lucide-react";

interface ContentTabProps {
  config: QRConfig;
  setConfig: (config: QRConfig) => void;
}

const typeIcons = {
  url: Globe,
  text: Type,
  email: Mail,
  phone: Phone,
  sms: MessageSquare,
  wifi: Wifi,
  vcard: User,
  location: MapPin,
};

export const ContentTab = ({ config, setConfig }: ContentTabProps) => {
  const updateContent = (field: keyof QRConfig, value: any) => {
    setConfig({ ...config, [field]: value });
  };

  const renderContentInput = () => {
    switch (config.type) {
      case "url":
        return (
          <div className="space-y-2">
            <Label htmlFor="url">Website URL</Label>
            <Input
              id="url"
              type="url"
              placeholder="https://example.com"
              value={config.content}
              onChange={(e) => updateContent("content", e.target.value)}
            />
          </div>
        );
      case "text":
        return (
          <div className="space-y-2">
            <Label htmlFor="text">Text Content</Label>
            <Textarea
              id="text"
              placeholder="Enter your text here..."
              value={config.content}
              onChange={(e) => updateContent("content", e.target.value)}
              rows={4}
            />
          </div>
        );
      case "email":
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">Email Address</Label>
              <Input
                id="email"
                type="email"
                placeholder="contact@example.com"
                value={config.content.split("?")[0].replace("mailto:", "")}
                onChange={(e) => updateContent("content", `mailto:${e.target.value}`)}
              />
            </div>
          </div>
        );
      case "phone":
        return (
          <div className="space-y-2">
            <Label htmlFor="phone">Phone Number</Label>
            <Input
              id="phone"
              type="tel"
              placeholder="+1234567890"
              value={config.content.replace("tel:", "")}
              onChange={(e) => updateContent("content", `tel:${e.target.value}`)}
            />
          </div>
        );
      case "sms":
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="sms-number">Phone Number</Label>
              <Input
                id="sms-number"
                type="tel"
                placeholder="+1234567890"
                value={config.content.split(":")[1]?.split("?")[0] || ""}
                onChange={(e) => updateContent("content", `sms:${e.target.value}`)}
              />
            </div>
          </div>
        );
      case "wifi": {
        const wifiParts = /^WIFI:T:(.*?);S:(.*?);P:(.*?);;$/.exec(config.content) || [];
        const [, wifiType = "WPA", wifiSsid = "", wifiPassword = ""] = wifiParts;
        const updateWifi = (next: { type?: string; ssid?: string; password?: string }) => {
          const type = next.type ?? wifiType;
          const ssid = next.ssid ?? wifiSsid;
          const password = next.password ?? wifiPassword;
          updateContent("content", `WIFI:T:${type};S:${ssid};P:${password};;`);
        };
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="wifi-ssid">Network Name (SSID)</Label>
              <Input
                id="wifi-ssid"
                placeholder="MyWiFi"
                value={wifiSsid}
                onChange={(e) => updateWifi({ ssid: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="wifi-password">Password</Label>
              <Input
                id="wifi-password"
                type="password"
                placeholder="password123"
                value={wifiPassword}
                onChange={(e) => updateWifi({ password: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="wifi-type">Security Type</Label>
              <Select value={wifiType} onValueChange={(value) => updateWifi({ type: value })}>
                <SelectTrigger id="wifi-type">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="WPA">WPA/WPA2</SelectItem>
                  <SelectItem value="WEP">WEP</SelectItem>
                  <SelectItem value="nopass">None</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        );
      }
      case "vcard": {
        const nameMatch = /FN:(.*)/.exec(config.content)?.[1] ?? "";
        const emailMatch = /EMAIL:(.*)/.exec(config.content)?.[1] ?? "";
        const phoneMatch = /TEL:(.*)/.exec(config.content)?.[1] ?? "";
        const updateVcard = (next: { name?: string; email?: string; phone?: string }) => {
          const name = next.name ?? nameMatch;
          const email = next.email ?? emailMatch;
          const phone = next.phone ?? phoneMatch;
          updateContent(
            "content",
            `BEGIN:VCARD\nVERSION:3.0\nFN:${name}\nTEL:${phone}\nEMAIL:${email}\nEND:VCARD`
          );
        };
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="vcard-name">Full Name</Label>
              <Input
                id="vcard-name"
                placeholder="John Doe"
                value={nameMatch}
                onChange={(e) => updateVcard({ name: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="vcard-email">Email</Label>
              <Input
                id="vcard-email"
                type="email"
                placeholder="john@example.com"
                value={emailMatch}
                onChange={(e) => updateVcard({ email: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="vcard-phone">Phone</Label>
              <Input
                id="vcard-phone"
                type="tel"
                placeholder="+1234567890"
                value={phoneMatch}
                onChange={(e) => updateVcard({ phone: e.target.value })}
              />
            </div>
          </div>
        );
      }
      case "location": {
        const [lat = "40.7128", lng = "-74.0060"] = config.content.replace("geo:", "").split(",");
        const updateLocation = (next: { lat?: string; lng?: string }) => {
          updateContent("content", `geo:${next.lat ?? lat},${next.lng ?? lng}`);
        };
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="location-lat">Latitude</Label>
              <Input
                id="location-lat"
                type="number"
                step="any"
                placeholder="40.7128"
                value={lat}
                onChange={(e) => updateLocation({ lat: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="location-lng">Longitude</Label>
              <Input
                id="location-lng"
                type="number"
                step="any"
                placeholder="-74.0060"
                value={lng}
                onChange={(e) => updateLocation({ lng: e.target.value })}
              />
            </div>
          </div>
        );
      }
      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      <div className="space-y-2">
        <Label htmlFor="type">QR Code Type</Label>
        <Select
          value={config.type}
          onValueChange={(value) => {
            const defaults: Record<string, string> = {
              url: "https://example.com",
              text: "",
              email: "mailto:",
              phone: "tel:",
              sms: "sms:",
              wifi: "WIFI:T:WPA;S:;P:;;",
              vcard: "BEGIN:VCARD\nVERSION:3.0\nFN:\nTEL:\nEMAIL:\nEND:VCARD",
              location: "geo:40.7128,-74.0060",
            };
            setConfig({ ...config, type: value as QRConfig["type"], content: defaults[value] ?? "" });
          }}
        >
          <SelectTrigger id="type">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {Object.entries(typeIcons).map(([key, Icon]) => (
              <SelectItem key={key} value={key}>
                <div className="flex items-center gap-2">
                  <Icon className="w-4 h-4" />
                  <span className="capitalize">{key}</span>
                </div>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {renderContentInput()}

      <div className="p-3 bg-primary/5 border border-primary/20 rounded-lg">
        <p className="text-xs text-muted-foreground">
          ?? Tip: Keep your content concise for better scanning reliability
